fn reading_preferences(demo_mode: bool) -> Preferences {
    let mut preferences = if demo_mode {
        Preferences::default()
    } else {
        Preferences::load()
    };
    if let Some(language) = std::env::args().find_map(|arg| {
        i18n::Language::from_tag(arg.strip_prefix("--language=")?)
    }) {
        preferences.language = language;
    }
    if std::env::args().any(|a| a == "--light") {
        preferences.appearance = Appearance::Light;
    } else if std::env::args().any(|a| a == "--dark") {
        preferences.appearance = Appearance::Dark;
    }
    if demo_mode {
        if std::env::args().any(|arg| arg == "--inter-demo") {
            preferences.font_family = preferences::FontFamily::Inter;
        }
        if std::env::args().any(|arg| arg == "--reference-demo") {
            preferences.apply_teams_reference();
            preferences.interface_zoom = 125;
        }
        for arg in std::env::args() {
            if let Some(value) = arg
                .strip_prefix("--font-demo=")
                .and_then(|value| value.parse().ok())
            {
                preferences.message_size = value;
            }
            if let Some(value) = arg
                .strip_prefix("--zoom-demo=")
                .and_then(|value| value.parse().ok())
            {
                preferences.interface_zoom = value;
            }
        }
    }
    preferences.normalize();
    preferences
}

fn main() -> iced::Result {
    if std::env::args().any(|arg| arg == "--trace-performance") {
        if let Err(error) = live_trace::enable() { eprintln!("Cannot enable performance trace: {error}"); }
    }
    if std::env::args().any(|arg| arg == "--perf-demo") {
        assert!(std::env::args().any(|arg| arg == "--demo"), "UI performance benchmarks require --demo");
        performance_ui::enable();
    }
    if std::env::args().any(|arg| arg == "--perf-bench") {
        assert!(std::env::args().any(|arg| arg == "--demo"), "Performance benchmarks require --demo");
        performance::run();
        return Ok(());
    }
    if std::env::args().nth(1).as_deref() == Some(auth_webview::HELPER_ARG) {
        if let Some(language) = std::env::args().find_map(|arg| {
            i18n::Language::from_tag(arg.strip_prefix("--language=")?)
        }) {
            i18n::set_language(language);
        }
        std::process::exit(auth_webview::helper_main());
    }
    if !std::env::args().any(|arg| arg == "--demo") {
        let _ = dotenvy::dotenv();
    }
    if let Some(query) = std::env::args().find_map(|arg|arg.strip_prefix("--diagnose-chat-media=").map(str::to_owned)) {
        let result = media_diagnostics::inspect(auth::AuthConfig::work(configured_client_id()), &query);
        println!("{}", match result { Ok(value)=>value, Err(stage)=>serde_json::json!({"error_stage":stage}) });
        return Ok(());
    }
    if std::env::args().any(|arg|arg == "--diagnose-calendar") {
        let result = media_diagnostics::calendar_status(auth::AuthConfig::work(configured_client_id()));
        println!("{}", match result { Ok(value)=>value, Err(stage)=>serde_json::json!({"error_stage":stage}) });
        return Ok(());
    }
    if std::env::args().any(|arg|arg == "--diagnose-notifications") {
        let result = media_diagnostics::notification_directory(auth::AuthConfig::work(configured_client_id()));
        println!("{}", match result { Ok(value)=>value, Err(stage)=>serde_json::json!({"error_stage":stage}) });
        return Ok(());
    }
    let initial_preferences = reading_preferences(std::env::args().any(|arg| arg == "--demo"));
    i18n::set_language(initial_preferences.language);
    typography::initialize(initial_preferences.font_family);
    iced::daemon(TeamsApp::boot, update, view)
        .title(window_title)
        .settings(iced::Settings {
            id: Some(APP_ID.into()),
            ..Default::default()
        })
        .default_font(typography::regular())
        .font(typography::REGULAR_BYTES)
        .font(typography::INTER_REGULAR_BYTES)
        .font(typography::INTER_SEMIBOLD_BYTES)
        .font(typography::MEDIUM_BYTES)
        .font(typography::SEMIBOLD_BYTES)
        .font(typography::BOLD_BYTES)
        .font(typography::ITALIC_BYTES)
        .font(typography::SEMIBOLD_ITALIC_BYTES)
        .font(typography::EMOJI_BYTES)
        .scale_factor(|state: &TeamsApp, _window| f32::from(state.preferences.interface_zoom) / 100.0)
        .theme(|state: &TeamsApp, _window| teams_theme(state.preferences.appearance))
        .subscription(subscription)
        .run()
}

fn window_icon() -> Option<iced::window::Icon> {
    iced::window::icon::from_rgba(
        include_bytes!("../assets/teams-linux-rs.rgba").to_vec(),
        256,
        256,
    )
    .ok()
}

fn app_window_settings(size: iced::Size, min: iced::Size) -> iced::window::Settings {
    iced::window::Settings {
        size,
        min_size: Some(min),
        position: iced::window::Position::Centered,
        exit_on_close_request: false,
        icon: window_icon(),
        platform_specific: iced::window::settings::PlatformSpecific {
            application_id: APP_ID.into(),
            ..Default::default()
        },
        ..Default::default()
    }
}

fn main_window_settings() -> iced::window::Settings {
    let scale = f32::from(reading_preferences(std::env::args().any(|arg| arg == "--demo")).interface_zoom) / 100.0;
    let demo = std::env::args().any(|arg| arg == "--demo");
    let size = if demo && std::env::args().any(|arg| arg == "--compact-demo") {
        iced::Size::new(880.0 / scale, 580.0 / scale)
    } else if demo && std::env::args().any(|arg| arg == "--reference-demo") {
        iced::Size::new(2560.0 / scale, 1416.0 / scale)
    } else if demo && std::env::args().any(|arg| arg == "--wide-demo") {
        iced::Size::new(1920.0 / scale, 1080.0 / scale)
    } else {
        iced::Size::new(1440.0 / scale, 920.0 / scale)
    };
    let mut settings = app_window_settings(size, iced::Size::new(880.0, 580.0));
    settings.decorations = false;
    settings.maximized = !demo || std::env::args().any(|arg| arg == "--maximized-demo");
    settings
}

fn call_window_settings() -> iced::window::Settings {
    let mut settings = app_window_settings(iced::Size::new(1100.0, 760.0), iced::Size::new(720.0, 560.0));
    // The chat window stays centered. The call opens at the corner so it does
    // not cover that screen.
    settings.position = iced::window::Position::Specific(iced::Point::new(64.0, 64.0));
    settings
}

fn call_window_wants_video_frames(state: &TeamsApp) -> bool {
    state.prejoin.as_ref().is_some_and(|join| join.preview.is_some())
        || state.native_call_snapshot.as_ref().is_some_and(|snapshot| {
            snapshot.camera_enabled || snapshot.camera_sending || snapshot.camera_receiving
        })
}

fn window_title(state: &TeamsApp, window: iced::window::Id) -> String {
    if state.call_window == Some(window) {
        let subject = state
            .prejoin
            .as_ref()
            .map(|join| join.subject.trim())
            .filter(|subject| !subject.is_empty())
            .unwrap_or(tr("Call"));
        return format!("{subject} — Teams Linux");
    }
    "Teams Linux".to_owned()
}

fn open_main_window(state: &mut TeamsApp) -> Task<AppMessage> {
    let settings = main_window_settings();
    state.main_window_maximized = settings.maximized;
    let (id, open) = iced::window::open(settings);
    state.main_window = Some(id);
    open.map(|_| AppMessage::WindowReady)
}

fn ensure_call_window(state: &mut TeamsApp) -> Task<AppMessage> {
    if state.prejoin.is_none() || state.call_window.is_some() {
        return Task::none();
    }
    let (id, open) = iced::window::open(call_window_settings());
    state.call_window = Some(id);
    open.map(|_| AppMessage::WindowReady)
}

fn focus_call_window(state: &TeamsApp) -> Task<AppMessage> {
    state.call_window.map_or_else(Task::none, |id| {
        iced::window::minimize(id, false).chain(iced::window::gain_focus(id))
    })
}

fn focus_main_window(state: &TeamsApp) -> Task<AppMessage> {
    if let Some(id) = state.main_window {
        return iced::window::minimize(id, false).chain(iced::window::gain_focus(id));
    }
    iced::window::latest().then(|window| {
        window.map_or_else(Task::none, |id| {
            iced::window::minimize(id, false).chain(iced::window::gain_focus(id))
        })
    })
}

