const MAX_INCOMING_CALL_NOTICES: usize = 5;
const MAX_RECENT_INCOMING_CALL_IDS: usize = 128;

fn unread_chat_total(chats: &[ChatSummary]) -> usize {
    chats
        .iter()
        .filter(|chat| chat_matches_filter(chat, ChatListFilter::Unread))
        .count()
}

fn unread_count_badge(count: usize) -> Element<'static, AppMessage> {
    let label = if count > 99 {
        "99+".to_owned()
    } else {
        count.to_string()
    };
    let width = if label.len() == 1 {
        15.0
    } else {
        8.0 + label.len() as f32 * 6.0
    };
    container(
        text(label)
            .size(10)
            .font(semibold())
            .style(ui_text(Tone::OnPrimary)),
    )
    .width(width)
    .height(15.0)
    .center_x(width)
    .center_y(15.0)
    .style(ui_surface(Tone::PresenceBusy, false, 8.0))
    .into()
}

fn chat_matches_filter(chat: &ChatSummary, filter: ChatListFilter) -> bool {
    if graph::is_private_feed_thread(&chat.id) { return false; }
    let hidden = chat.hidden == Some(true);
    match filter {
        ChatListFilter::Recent => !hidden,
        ChatListFilter::Hidden => hidden,
        ChatListFilter::Unread => !hidden && chat.unread == Some(true),
        ChatListFilter::Chats => !hidden && !chat.group_avatar.meeting,
        ChatListFilter::Meetings => !hidden && chat.group_avatar.meeting,
        ChatListFilter::Drafts | ChatListFilter::Mentions => !hidden,
    }
}

#[cfg(test)]
mod unread_badge_tests {
    use super::*;

    #[test]
    fn unread_chat_total_skips_read_hidden_and_private_feeds() {
        let mut unread = ChatSummary::default();
        unread.id = "19:one".into();
        unread.unread = Some(true);
        let mut read = ChatSummary::default();
        read.id = "19:two".into();
        let mut hidden = unread.clone();
        hidden.id = "19:hid".into();
        hidden.hidden = Some(true);
        let mut feed = unread.clone();
        feed.id = "48:notifications".into();
        assert_eq!(unread_chat_total(&[unread, read, hidden, feed]), 1);
        assert_eq!(unread_chat_total(&[]), 0);
    }
}

