#[derive(Clone, Debug, PartialEq, Eq)]
struct PendingReaction {
    epoch: u64,
    chat_id: String,
    message_id: String,
    emoji: String,
    remove: bool,
}

impl PendingReaction {
    fn targets(&self, epoch: u64, chat_id: &str, message_id: &str) -> bool {
        self.epoch == epoch && self.chat_id == chat_id && self.message_id == message_id
    }

    fn matches_operation(
        &self,
        epoch: u64,
        chat_id: &str,
        message_id: &str,
        emoji: &str,
        remove: bool,
    ) -> bool {
        self.targets(epoch, chat_id, message_id)
            && self.emoji == emoji
            && self.remove == remove
    }
}

fn reaction_is_pending(
    pending: &[PendingReaction],
    epoch: u64,
    chat_id: &str,
    message_id: &str,
) -> bool {
    pending
        .iter()
        .any(|reaction| reaction.targets(epoch, chat_id, message_id))
}

fn finish_pending_reaction(
    pending: &mut Vec<PendingReaction>,
    epoch: u64,
    chat_id: &str,
    message_id: &str,
    emoji: &str,
    remove: bool,
) -> bool {
    let Some(index) = pending.iter().position(|reaction| {
        reaction.matches_operation(epoch, chat_id, message_id, emoji, remove)
    }) else {
        return false;
    };
    pending.remove(index);
    true
}

