const HISTORY_VIRTUALIZE_AFTER: usize = 40;
const HISTORY_MAX_MATERIALIZED: usize = 120;
const HISTORY_OVERSCAN_PX: f32 = 480.0;
const TYPING_INDICATOR_MIN_INTERVAL: Duration = Duration::from_secs(4);
const GLOBAL_MESSAGE_SEARCH_PAGE_SIZE: usize = 10;
const GLOBAL_MESSAGE_JUMP_PAGE_BUDGET: u8 = 12;
const CONVERSATION_SEARCH_PAGE_BUDGET: u8 = 12;
const REPLY_ORIGIN_PAGE_BUDGET: u8 = 12;

enum GlobalMessageJumpProgress {
    NotPending,
    Found(Task<AppMessage>),
    Loading(Task<AppMessage>),
    Exhausted,
}

enum ReplyOriginNavigationProgress {
    NotPending,
    Waiting,
    Found(Task<AppMessage>),
    Loading(Task<AppMessage>),
    Exhausted,
}

enum GlobalChannelMessageJumpProgress {
    NotPending,
    Waiting,
    Found(Task<AppMessage>),
    Loading(Task<AppMessage>),
    Missing,
}

fn advance_global_channel_message_jump(
    state: &mut TeamsApp,
) -> GlobalChannelMessageJumpProgress {
    let Some(jump) = state.pending_global_channel_message_jump.clone() else {
        return GlobalChannelMessageJumpProgress::NotPending;
    };
    if jump.epoch != state.session_epoch
        || state.section != Section::Teams
        || state.selected_team.as_deref() != Some(jump.team_id.as_str())
        || state.selected_channel.as_deref() != Some(jump.channel_id.as_str())
    {
        state.pending_global_channel_message_jump = None;
        return GlobalChannelMessageJumpProgress::NotPending;
    }
    if state.loading_channel_messages {
        return GlobalChannelMessageJumpProgress::Waiting;
    }
    if state
        .channel_messages
        .iter()
        .any(|message| message.id == jump.message_id)
    {
        state.selected_message = Some(jump.message_id.clone());
        state.pending_global_channel_message_jump = None;
        state.pending_history_anchor = None;
        state.follow_tail = false;
        state.status.clear();
        let epoch = jump.epoch;
        let team_id = jump.team_id;
        let channel_id = jump.channel_id;
        let message_id = jump.message_id;
        return GlobalChannelMessageJumpProgress::Found(Task::perform(
            async move { futures_timer::Delay::new(Duration::from_millis(50)).await },
            move |_| {
                AppMessage::FinishGlobalChannelMessageJump(epoch, team_id, channel_id, message_id)
            },
        ));
    }
    if state.loading_channel_history {
        return GlobalChannelMessageJumpProgress::Waiting;
    }
    if state.channel_history_before.is_some() && jump.pages_remaining > 0 {
        if let Some(pending) = &mut state.pending_global_channel_message_jump {
            pending.pages_remaining = pending.pages_remaining.saturating_sub(1);
        }
        let epoch = jump.epoch;
        let team_id = jump.team_id;
        let channel_id = jump.channel_id;
        return GlobalChannelMessageJumpProgress::Loading(Task::perform(
            async move { futures_timer::Delay::new(Duration::from_millis(30)).await },
            move |_| AppMessage::ContinueGlobalChannelMessageJump(epoch, team_id, channel_id),
        ));
    }

    state.pending_global_channel_message_jump = None;
    state.selected_message = None;
    state.status = if state.channel_history_before.is_some() {
        tr("The channel opened, but the message was not found in the 12 earlier pages.").into()
    } else {
        tr("The channel opened, but the returned history does not contain the message.").into()
    };
    GlobalChannelMessageJumpProgress::Missing
}

fn typing_indicator_due(last_sent: Option<Instant>, now: Instant) -> bool {
    last_sent.is_none_or(|last_sent| {
        now.checked_duration_since(last_sent)
            .is_some_and(|elapsed| elapsed >= TYPING_INDICATOR_MIN_INTERVAL)
    })
}

fn global_search_query_ready(query: &str, demo_mode: bool) -> bool {
    !demo_mode
        && query.trim().chars().count() >= 2
        && query.trim().chars().take(257).count() <= 256
}

fn advance_global_message_jump(state: &mut TeamsApp) -> GlobalMessageJumpProgress {
    let Some(jump) = state.pending_global_message_jump.clone() else {
        return GlobalMessageJumpProgress::NotPending;
    };
    if jump.epoch != state.session_epoch
        || state.section != Section::Chats
        || state.selected_chat.as_deref() != Some(jump.chat_id.as_str())
    {
        state.pending_global_message_jump = None;
        return GlobalMessageJumpProgress::NotPending;
    }

    if let Some(index) = state
        .messages
        .iter()
        .position(|message| message.id == jump.message_id)
    {
        let matches = message_search_match_indices(&state.messages, &jump.query);
        state.message_search_open = true;
        state.message_search_query = jump.query;
        state.message_search_result_index = matches
            .iter()
            .position(|candidate| *candidate == index)
            .unwrap_or_default();
        state.selected_message = Some(state.messages[index].id.clone());
        state.pending_global_message_jump = None;
        state.pending_history_anchor = None;
        state.follow_tail = false;
        state.status.clear();

        let epoch = state.session_epoch;
        let chat_id = jump.chat_id;
        let message_id = jump.message_id;
        return GlobalMessageJumpProgress::Found(Task::perform(
            async move { futures_timer::Delay::new(Duration::from_millis(50)).await },
            move |_| AppMessage::FinishGlobalMessageJump(epoch, chat_id, message_id),
        ));
    }

    if state.history_before.is_some() && jump.pages_remaining > 0 {
        if let Some(pending) = &mut state.pending_global_message_jump {
            pending.pages_remaining = pending.pages_remaining.saturating_sub(1);
        }
        let epoch = jump.epoch;
        let chat_id = jump.chat_id;
        return GlobalMessageJumpProgress::Loading(Task::perform(
            async move { futures_timer::Delay::new(Duration::from_millis(30)).await },
            move |_| AppMessage::ContinueGlobalMessageJump(epoch, chat_id),
        ));
    }

    state.pending_global_message_jump = None;
    state.message_search_open = true;
    state.message_search_query = jump.query;
    state.message_search_result_index = 0;
    state.selected_message = None;
    state.status = if state.history_before.is_some() {
        tr("The message was not found in the recent pages. Select Search older messages to continue.").into()
    } else {
        tr("The conversation opened, but the service did not return the matching message.").into()
    };
    GlobalMessageJumpProgress::Exhausted
}

fn advance_reply_origin_navigation(state: &mut TeamsApp) -> ReplyOriginNavigationProgress {
    let Some(navigation) = state.pending_reply_origin_navigation.clone() else {
        return ReplyOriginNavigationProgress::NotPending;
    };
    if navigation.epoch != state.session_epoch
        || state.section != Section::Chats
        || state.selected_chat.as_deref() != Some(navigation.chat_id.as_str())
    {
        state.pending_reply_origin_navigation = None;
        return ReplyOriginNavigationProgress::NotPending;
    }

    if let Some(index) = state
        .messages
        .iter()
        .position(|message| message.id == navigation.message_id)
    {
        state.pending_reply_origin_navigation = None;
        state.selected_message = Some(navigation.message_id);
        state.pending_history_anchor = None;
        state.follow_tail = false;
        state.status.clear();
        return ReplyOriginNavigationProgress::Found(reveal_history_message(state, index));
    }

    if state.loading_history {
        return ReplyOriginNavigationProgress::Waiting;
    }

    if state.history_before.is_some() && navigation.pages_remaining > 0 {
        if let Some(pending) = &mut state.pending_reply_origin_navigation {
            pending.pages_remaining = pending.pages_remaining.saturating_sub(1);
        }
        state.status = tr("Looking for the original message in older history…").into();
        let epoch = navigation.epoch;
        let chat_id = navigation.chat_id;
        let message_id = navigation.message_id;
        return ReplyOriginNavigationProgress::Loading(Task::perform(
            async move { futures_timer::Delay::new(Duration::from_millis(40)).await },
            move |_| AppMessage::ContinueReplyOriginNavigation(epoch, chat_id, message_id),
        ));
    }

    state.pending_reply_origin_navigation = None;
    state.status = if state.history_before.is_some() {
        format!(
            "The original message was not found in the previous {REPLY_ORIGIN_PAGE_BUDGET} pages. Try again to look further back."
        )
    } else {
        tr("The original message is outside the available history.").into()
    };
    ReplyOriginNavigationProgress::Exhausted
}

fn person_identity_line(person: &PersonSearchResult) -> String {
    let email = person.email.trim();
    let title = person
        .job_title
        .as_deref()
        .map(str::trim)
        .filter(|title| !title.is_empty());
    match (email.is_empty(), title) {
        (false, Some(title)) => format!("{email} · {title}"),
        (false, None) => email.to_owned(),
        (true, Some(title)) => title.to_owned(),
        (true, None) => tr("Contact information unavailable").into(),
    }
}

fn merge_hidden_chat_cache(
    mut latest: Vec<ChatSummary>,
    cached: Vec<hidden_chats::HiddenChat>,
) -> Vec<ChatSummary> {
    latest.retain(|chat| !graph::is_private_feed_thread(&chat.id));
    for stored in cached {
        if graph::is_private_feed_thread(&stored.id) { continue; }
        if let Some(remote) = latest.iter_mut().find(|chat| chat.id == stored.id) {
            if remote.hidden.is_none() {
                remote.hidden = Some(true);
            }
            continue;
        }
        latest.push(ChatSummary {
            id: stored.id,
            title: stored.title,
            subtitle: if stored.is_group {
                tr("Group chat · hidden").into()
            } else {
                tr("Direct chat · hidden").into()
            },
            preview: String::new(),
            is_group: stored.is_group,
            hidden: Some(true),
            ..ChatSummary::default()
        });
    }
    latest
}

fn load_chats_with_hidden_cache(session: TeamsSession) -> Result<LoadedChats, String> {
    let mut loaded = graph::load_chats(session)?;
    if let Some(store) = hidden_chats::Store::for_account(&loaded.user_id) {
        if let Ok(cached) = store.load() {
            loaded.chats = merge_hidden_chat_cache(loaded.chats, cached);
        }
    }
    Ok(loaded)
}

fn update_hidden_chat_cache_task(
    account_id: String,
    epoch: u64,
    chat_id: String,
    title: String,
    is_group: bool,
    hidden: bool,
) -> Task<AppMessage> {
    let request_chat_id = chat_id.clone();
    Task::perform(
        async move {
            let store = hidden_chats::Store::for_account(&account_id)
                .ok_or_else(|| {
                    tr("Could not identify the account for the local cache.").to_owned()
                })?;
            store.set_hidden(&request_chat_id, &title, is_group, hidden)
        },
        move |result| AppMessage::HiddenChatCacheSaved(epoch, chat_id, hidden, result),
    )
}

fn loaded_message_person(
    state: &TeamsApp,
    message_id: &str,
    forwarded_author: bool,
) -> Option<PersonSearchResult> {
    if state.demo_mode {
        return None;
    }
    let message = match state.section {
        Section::Chats
            if state.selected_chat.as_deref().is_some_and(|chat_id| {
                state.chat_messages_loaded_for.as_deref() == Some(chat_id)
            }) =>
        {
            state
                .messages
                .iter()
                .find(|message| message.id == message_id)
        }
        Section::Teams
            if state.selected_team.is_some()
                && state.selected_channel.is_some()
                && !state.loading_channel_messages =>
        {
            state
                .channel_messages
                .iter()
                .find(|message| message.id == message_id)
        }
        _ => None,
    }?;
    if message.is_deleted || message.id.starts_with("local:") {
        return None;
    }
    let (display_name, person_id) = if forwarded_author {
        let forwarded = message.forwarded.as_ref()?;
        (
            forwarded.author.as_deref()?,
            forwarded.author_id.as_deref()?,
        )
    } else {
        if message.is_mine {
            return None;
        }
        (message.author.as_str(), message.author_id.as_deref()?)
    };
    let display_name = display_name.trim();
    let person_id = avatars::person_id(person_id)?;
    (!display_name.is_empty()).then(|| PersonSearchResult {
        id: person_id.clone(),
        display_name: sender_names::resolve(display_name,Some(&person_id),&state.identity_names()),
        email: String::new(),
        job_title: None,
    })
}

fn loaded_reaction_person(
    state: &TeamsApp,
    message_id: &str,
    participant_id: &str,
) -> Option<PersonSearchResult> {
    if state.demo_mode
        || state.section != Section::Chats
        || !state.selected_chat.as_deref().is_some_and(|chat_id| {
            state.chat_messages_loaded_for.as_deref() == Some(chat_id)
        })
    {
        return None;
    }
    let message = state
        .messages
        .iter()
        .find(|message| message.id == message_id && !message.id.starts_with("local:"))?;
    if message.is_deleted {
        return None;
    }
    let target_id = avatars::person_id(participant_id)?;
    let reactor = message
        .reactions
        .iter()
        .flat_map(|reaction| &reaction.reactors)
        .find(|reactor| {
            avatars::person_id(&reactor.id).as_deref() == Some(target_id.as_str())
        })?;
    let names = state.identity_names();
    let display_name = if reaction_identity(&target_id) == reaction_identity(&state.user_id) {
        state.user_name.trim()
    } else if !reactor.name.trim().is_empty() {
        reactor.name.trim()
    } else {
        names.get(&reaction_identity(&target_id)).map(String::as_str).unwrap_or_default()
    };
    (!display_name.is_empty()).then(|| PersonSearchResult {
        id: target_id,
        display_name: display_name.to_owned(),
        email: String::new(),
        job_title: None,
    })
}

fn global_people_result_is_current(
    result_epoch: u64,
    result_sequence: u64,
    result_query: &str,
    session_epoch: u64,
    current_sequence: u64,
    current_query: &str,
) -> bool {
    result_epoch == session_epoch
        && result_sequence == current_sequence
        && result_query == current_query.trim()
}

fn merge_global_message_results(
    current: &mut Vec<graph::MessageSearchResult>,
    incoming: Vec<graph::MessageSearchResult>,
) {
    let mut seen = current
        .iter()
        .map(|hit| (hit.chat_id.clone(), hit.message_id.clone()))
        .collect::<HashSet<_>>();
    for hit in incoming {
        if seen.insert((hit.chat_id.clone(), hit.message_id.clone())) {
            current.push(hit);
        }
    }
}

fn local_search_people(state: &TeamsApp, query: &str) -> Vec<PersonSearchResult> {
    let query = query.to_lowercase();
    let owner = avatars::person_id(&state.user_id);
    let mut seen = HashSet::new();
    state.chats.iter()
        .filter(|chat| !chat.is_group && chat.hidden != Some(true)
            && chat_sidebar_ui::title_matches_query(&chat.title, &query))
        .filter_map(|chat| {
            let id = state.chat_person_id(chat)?;
            (Some(&id) != owner.as_ref() && seen.insert(id.clone())).then(|| PersonSearchResult {
                id,
                display_name: chat.title.clone(),
                email: String::new(),
                job_title: None,
            })
        })
        .take(20)
        .collect()
}

fn message_search_match_indices(messages: &[GraphMessage], query: &str) -> Vec<usize> {
    let terms = message_body::search_terms(query);
    if terms.is_empty() {
        return Vec::new();
    }
    messages
        .iter()
        .enumerate()
        .filter_map(|(index, message)| message_matches_search(message, &terms).then_some(index))
        .collect()
}

fn message_matches_search(message: &GraphMessage, terms: &[String]) -> bool {
    if terms.is_empty() {
        return false;
    }

    let optional_field_len = |value: Option<&str>| value.map_or(0, str::len);
    let forwarded_capacity = message.forwarded.as_ref().map_or(0, |forwarded| {
        optional_field_len(forwarded.author.as_deref())
            .saturating_add(optional_field_len(forwarded.subject.as_deref()))
            .saturating_add(forwarded.content.len())
    });
    let quoted_capacity = optional_field_len(message.quoted_author.as_deref())
        .saturating_add(optional_field_len(message.quoted_body.as_deref()));
    let mut normalized = String::with_capacity(
        message
            .body
            .len()
            .saturating_add(message.author.len())
            .saturating_add(
                message
                    .files
                    .iter()
                    .map(|file| file.name.len())
                    .fold(0usize, usize::saturating_add),
            )
            .saturating_add(forwarded_capacity)
            .saturating_add(quoted_capacity),
    );
    let mut fields = Vec::with_capacity(5 + message.files.len());
    append_normalized_search_field(&mut normalized, &mut fields, &message.body);
    append_normalized_search_field(&mut normalized, &mut fields, &message.author);
    for file in &message.files {
        append_normalized_search_field(&mut normalized, &mut fields, &file.name);
    }
    if let Some(forwarded) = &message.forwarded {
        if let Some(author) = &forwarded.author {
            append_normalized_search_field(&mut normalized, &mut fields, author);
        }
        if let Some(subject) = &forwarded.subject {
            append_normalized_search_field(&mut normalized, &mut fields, subject);
        }
        append_normalized_search_field(&mut normalized, &mut fields, &forwarded.content);
    }
    if let Some(quoted_author) = &message.quoted_author {
        append_normalized_search_field(&mut normalized, &mut fields, quoted_author);
    }
    if let Some(quoted_body) = &message.quoted_body {
        append_normalized_search_field(&mut normalized, &mut fields, quoted_body);
    }
    terms.iter().all(|term| {
        fields
            .iter()
            .any(|field| normalized[field.clone()].contains(term.as_str()))
    })
}

fn append_normalized_search_field(
    normalized: &mut String,
    fields: &mut Vec<Range<usize>>,
    value: &str,
) {
    let start = normalized.len();
    for character in value.chars() {
        normalized.extend(character.to_lowercase());
    }
    if normalized.len() > start {
        fields.push(start..normalized.len());
    }
}

fn newest_unloaded_search_match(
    messages: &[GraphMessage],
    loaded_ids: &HashSet<String>,
    query: &str,
) -> Option<String> {
    let terms = message_body::search_terms(query);
    if terms.is_empty() {
        return None;
    }
    messages
        .iter()
        .filter(|message| {
            !message.id.is_empty()
                && !loaded_ids.contains(&message.id)
                && message_matches_search(message, &terms)
        })
        .max_by(|left, right| {
            left.timestamp
                .cmp(&right.timestamp)
                .then_with(|| left.id.cmp(&right.id))
        })
        .map(|message| message.id.clone())
}

fn message_search_selected_index(
    messages: &[GraphMessage],
    matches: &[usize],
    selected_message_id: Option<&str>,
    fallback: usize,
) -> Option<usize> {
    if matches.is_empty() {
        return None;
    }
    selected_message_id
        .and_then(|selected_id| {
            matches.iter().position(|message_index| {
                messages
                    .get(*message_index)
                    .is_some_and(|message| message.id == selected_id)
            })
        })
        .or(Some(fallback.min(matches.len() - 1)))
}

fn reveal_history_message(state: &TeamsApp, index: usize) -> Task<AppMessage> {
    let Some(message_id) = state
        .active_messages()
        .get(index)
        .map(|message| message.id.clone())
    else {
        return Task::none();
    };
    let fallback = history_message_scroll_offset(state, index);
    iced::advanced::widget::operate(history_scroll::locate_message(
        history_scroll::message_anchor(&message_id),
        fallback,
    ))
    .map(move |offset| AppMessage::RevealHistoryOffset(message_id.clone(), offset))
}

fn history_message_scroll_offset(state: &TeamsApp, index: usize) -> Option<f32> {
    let messages = state.active_messages();
    let (width, compact) = state
        .history_viewport
        .as_ref()
        .filter(|viewport| Some(viewport.chat_id.as_str()) == state.active_history_id())
        .map(|viewport| (viewport.viewport_width, viewport.compact))
        .unwrap_or((720.0, false));
    let heights = estimated_history_heights(messages, width, compact, &state.preferences);
    let message_top = (if compact { 12.0 } else { 20.0 })
        + if state.section == Section::Chats && state.history_before.is_some() {
            48.0
        } else {
            0.0
        }
        + heights.get(..index)?.iter().sum::<f32>();
    Some((message_top - 28.0).max(0.0))
}

fn history_message_scroll_task(state: &TeamsApp, index: usize) -> Task<AppMessage> {
    let Some(active_id) = state.active_history_id() else {
        return Task::none();
    };
    let messages = state.active_messages();
    let Some(viewport) = state
        .history_viewport
        .as_ref()
        .filter(|viewport| viewport.chat_id == active_id)
    else {
        return Task::none();
    };
    let heights = estimated_history_heights(
        messages,
        viewport.viewport_width,
        viewport.compact,
        &state.preferences,
    );
    let target = history_message_scroll_target(
        &heights,
        index,
        viewport,
        if viewport.compact { 12.0 } else { 20.0 },
        if state.section == Section::Chats && state.history_before.is_some() {
            48.0
        } else {
            0.0
        },
    );
    target.map_or_else(Task::none, |target| {
        iced::widget::operation::scroll_to::<AppMessage>(
            "message-history",
            iced::widget::operation::AbsoluteOffset {
                x: None,
                y: Some(target),
            },
        )
    })
}

#[derive(Debug, Clone, PartialEq)]
struct HistoryWindow {
    range: Range<usize>,
    before_height: f32,
    after_height: f32,
}

fn native_history_window(count: usize) -> HistoryWindow {
    HistoryWindow { range: 0..count, before_height: 0.0, after_height: 0.0 }
}

#[cfg(test)]
fn virtual_history_window(
    heights: &[f32],
    offset_y: Option<f32>,
    viewport_height: f32,
) -> HistoryWindow {
    let mut cumulative = Vec::with_capacity(heights.len());
    let mut sum = 0.0;
    for height in heights { sum += height.max(1.0); cumulative.push(sum); }
    virtual_history_window_from_prefix(&cumulative, offset_y, viewport_height)
}

#[cfg(test)]
fn virtual_history_window_from_prefix(
    cumulative: &[f32], offset_y: Option<f32>, viewport_height: f32,
) -> HistoryWindow {
    let total = cumulative.last().copied().unwrap_or(0.0);
    if cumulative.len() <= HISTORY_VIRTUALIZE_AFTER {
        return HistoryWindow { range: 0..cumulative.len(), before_height: 0.0, after_height: 0.0 };
    }
    let viewport_height = if viewport_height.is_finite() && viewport_height > 0.0 {
        viewport_height.clamp(240.0, 4_000.0)
    } else {
        720.0
    };
    let offset_y = offset_y
        .filter(|offset| offset.is_finite())
        .unwrap_or_else(|| (total - viewport_height).max(0.0))
        .clamp(0.0, (total - viewport_height).max(0.0));
    let lower = (offset_y - HISTORY_OVERSCAN_PX).max(0.0);
    let upper = (offset_y + viewport_height + HISTORY_OVERSCAN_PX).min(total);
    let mut start = cumulative.partition_point(|end| *end <= lower);
    let mut end = if upper >= total {
        cumulative.len()
    } else {
        cumulative.partition_point(|end| *end < upper)
    }
    .max(start + 1);
    end = end.min(cumulative.len());

    if end - start > HISTORY_MAX_MATERIALIZED {
        let center = (lower + upper) * 0.5;
        let center_index = cumulative.partition_point(|end| *end <= center);
        start = center_index.saturating_sub(HISTORY_MAX_MATERIALIZED / 2);
        end = (start + HISTORY_MAX_MATERIALIZED).min(cumulative.len());
        if end == cumulative.len() {
            start = end.saturating_sub(HISTORY_MAX_MATERIALIZED);
        }
    }

    HistoryWindow {
        before_height: start.checked_sub(1).map_or(0.0, |i| cumulative[i]),
        after_height: total - end.checked_sub(1).map_or(0.0, |i| cumulative[i]),
        range: start..end,
    }
}

fn history_message_height(
    message: &GraphMessage,
    previous: Option<&GraphMessage>,
    pane_width: f32,
    compact: bool,
    preferences: &Preferences,
) -> f32 {
    let grouped = previous.is_some_and(|previous| group_messages(previous, message));
    let bubble_width = message_body::bubble_width(pane_width, message.is_mine, compact);
    let content_width = (bubble_width - 28.0).max(48.0);
    let image_width = content_width.min(images::INLINE_MAX_WIDTH);
    let font_size = f32::from(preferences.message_size);
    let columns = (content_width / (font_size * 0.54)).floor().max(1.0) as usize;
    let (text_lines, image_height, block_count) = if let Some(document) = &message.rich {
        let (lines, inline_height) = document.estimated_layout(columns, content_width);
        let image_height = if document.contains_inline_images() {
            inline_height
        } else {
            message
                .images
                .iter()
                .map(|image| images::display_size(image, 0, 0, image_width, images::INLINE_MAX_HEIGHT).1)
                .sum()
        };
        (lines, image_height, document.blocks.len())
    } else {
        (
            message_body::Document::estimated_plain_lines(&message.body, columns),
            message
                .images
                .iter()
                .map(|image| images::display_size(image, 0, 0, image_width, images::INLINE_MAX_HEIGHT).1)
                .sum(),
            usize::from(!message.body.is_empty()),
        )
    };
    let line_height = font_size * preferences.line_height();
    let file_columns = ((image_width - 52.0) / (13.0 * 0.54)).floor().max(1.0) as usize;
    let file_height: f32 = message
        .files
        .iter()
        .map(|file| {
            let name_lines = file.name.chars().count().div_ceil(file_columns).max(1);
            let thumbnail_height = images::attachment_thumbnail(file, &message.images)
                .map_or(0.0, |preview| {
                    let width = images::FILE_THUMBNAIL_WIDTH.min((content_width - 20.0).max(1.0));
                    images::display_size(&preview, 0, 0, width, images::INLINE_MAX_HEIGHT).1 + 8.0
                });
            (name_lines as f32 + 1.0) * (13.0 * preferences.line_height()) + 20.0 + thumbnail_height
        })
        .sum();
    let body_height = text_lines as f32 * line_height
        + image_height
        + file_height
        + if message.reply_to.is_some() { 64.0 } else { 0.0 }
        + if message_priority_label(message.importance).is_some() { 18.0 } else if message.edited { 14.0 } else { 0.0 }
        + block_count.saturating_sub(1) as f32 * 8.0;
    let bubble_height = (body_height + 20.0).max(20.0);
    let header_height = if grouped { 0.0 } else { 23.0 };
    let reaction_height = if message.reactions.is_empty() { 0.0 } else { REACTION_CHIP_HEIGHT + 6.0 };
    let row_height = (if grouped { 4.0 } else { 20.0 })
        + header_height
        + bubble_height.max(28.0)
        + reaction_height;
    let date_separator = if !message.date.is_empty()
        && previous.is_none_or(|previous| previous.date != message.date)
    {
        42.0
    } else {
        0.0
    };
    (row_height + date_separator).clamp(36.0, 1_000_000.0)
}

fn message_priority_label(importance: ost::api::MessageImportance) -> Option<&'static str> {
    match importance {
        ost::api::MessageImportance::High => Some("IMPORTANTE"),
        ost::api::MessageImportance::Urgent => Some("URGENTE"),
        ost::api::MessageImportance::Normal => None,
    }
}

fn priority_bang() -> Element<'static, AppMessage> {
    text("!")
        .size(18)
        .font(semibold())
        .style(ui_text(Tone::PresenceBusy))
        .into()
}

fn estimated_history_heights(
    messages: &[GraphMessage],
    pane_width: f32,
    compact: bool,
    preferences: &Preferences,
) -> Vec<f32> {
    messages
        .iter()
        .enumerate()
        .map(|(index, message)| {
            let previous = index.checked_sub(1).and_then(|index| messages.get(index));
            history_message_height(message, previous, pane_width, compact, preferences)
        })
        .collect()
}

fn history_message_scroll_target(
    heights: &[f32],
    index: usize,
    viewport: &HistoryViewport,
    top_padding: f32,
    leading_content: f32,
) -> Option<f32> {
    let height = *heights.get(index)?;
    let message_top = top_padding
        + leading_content
        + heights[..index].iter().sum::<f32>();
    let message_bottom = message_top + height;
    let margin = 28.0;
    if message_top < viewport.offset_y + margin {
        Some((message_top - margin).max(0.0))
    } else if message_bottom > viewport.offset_y + viewport.viewport_height - margin {
        Some((message_bottom - viewport.viewport_height + margin).max(0.0))
    } else {
        None
    }
}

fn history_anchor_target(anchor: &HistoryViewport, current: &HistoryViewport) -> Option<f32> {
    if anchor.chat_id != current.chat_id {
        return None;
    }
    let added_height = current.content_height - anchor.content_height;
    if !added_height.is_finite() || added_height.abs() <= 1.0 || !anchor.offset_y.is_finite() {
        return None;
    }
    Some((anchor.offset_y + added_height).max(0.0))
}

