struct ImageViewer {
    scope: String,
    images: Vec<images::InlineImage>,
    index: usize,
    original: Option<images::OriginalImage>,
    loading: bool,
    error: Option<String>,
    feedback: Option<String>,
    busy: bool,
    zoom: f32,
}

impl ImageViewer {
    fn current(&self) -> Option<&images::InlineImage> {
        self.images.get(self.index)
    }

    fn navigate(&mut self, delta: i8) -> bool {
        if self.loading || self.busy {
            return false;
        }
        let next = if delta < 0 {
            self.index.checked_sub(delta.unsigned_abs() as usize)
        } else {
            self.index.checked_add(delta as usize)
        };
        let Some(next) = next.filter(|next| *next < self.images.len()) else {
            return false;
        };
        if next == self.index {
            return false;
        }
        self.index = next;
        self.original = None;
        self.loading = true;
        self.error = None;
        self.feedback = None;
        self.busy = false;
        self.zoom = 1.0;
        true
    }

    fn zoom_by(&mut self, delta: i8) {
        self.zoom = (self.zoom + f32::from(delta) * 0.25).clamp(0.25, 5.0);
    }

    fn zoom_by_wheel(&mut self, lines: f32) {
        if !lines.is_finite() || lines == 0.0 {
            return;
        }
        let factor = 1.1_f32.powf(lines);
        if !factor.is_finite() {
            return;
        }
        self.zoom = (self.zoom * factor).clamp(0.25, 5.0);
    }
}

