fn panel_style(
    background: Color,
    border: Color,
    radius: f32,
) -> impl Fn(&Theme) -> container::Style {
    move |theme| container::Style {
        background: Some(Background::Color(shade(theme, background, true))),
        border: Border::default()
            .rounded(radius)
            .color(shade(theme, border, true))
            .width(if border == Color::TRANSPARENT {
                0.0
            } else {
                1.0
            }),
        ..container::Style::default()
    }
}

fn button_style(
    background: Color,
    hover: Color,
    foreground: Color,
    border: Color,
    radius: f32,
) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |theme, status| {
        let background = if matches!(status, button::Status::Hovered | button::Status::Pressed) {
            hover
        } else {
            background
        };
        button::Style {
            background: Some(Background::Color(shade(theme, background, true))),
            text_color: shade(theme, foreground, false),
            border: Border::default()
                .rounded(radius)
                .color(shade(theme, border, true))
                .width(if border == Color::TRANSPARENT {
                    0.0
                } else {
                    1.0
                }),
            ..button::Style::default()
        }
    }
}

