fn hint<'a>(
    content: impl Into<Element<'a, AppMessage>>,
    label: impl Into<String>,
) -> Element<'a, AppMessage> {
    tooltip(
        content,
        container(text(label.into()).size(12).style(ui_text(Tone::Text)))
            .padding([7, 10])
            .style(ui_surface(Tone::Surface, true, 6.0)),
        tooltip::Position::Bottom,
    )
    .delay(std::time::Duration::from_millis(450))
    .into()
}

fn presence_tone(availability: presence::Availability) -> Tone {
    match availability {
        presence::Availability::Available | presence::Availability::AvailableIdle => Tone::PresenceAvailable,
        presence::Availability::Busy | presence::Availability::BusyIdle
        | presence::Availability::DoNotDisturb => Tone::PresenceBusy,
        presence::Availability::BeRightBack | presence::Availability::Away => Tone::PresenceAway,
        presence::Availability::Offline => Tone::PresenceOffline,
        presence::Availability::Unknown => Tone::Secondary,
    }
}

// Keep the six supported reactions visible independently of system emoji fonts.
fn reaction_glyph(emoji: &str, size: f32) -> Element<'static, AppMessage> {
    if let Some(glyph) = reaction_catalog::glyph(emoji, size) { return glyph; }
    static HANDLES: std::sync::OnceLock<[svg::Handle; 6]> = std::sync::OnceLock::new();
    let index = match emoji {
        "👍" => Some(0), "❤️" | "❤" => Some(1), "😂" => Some(2),
        "😮" => Some(3), "😢" => Some(4), "😠" => Some(5), _ => None,
    };
    if let Some(index) = index {
        let handles = HANDLES.get_or_init(|| [
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-like.svg").as_slice()),
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-heart.svg").as_slice()),
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-laugh.svg").as_slice()),
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-surprised.svg").as_slice()),
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-sad.svg").as_slice()),
            svg::Handle::from_memory(include_bytes!("../assets/icons/reaction-angry.svg").as_slice()),
        ]);
        svg(handles[index].clone()).width(size).height(size).into()
    } else {
        text(emoji.to_owned()).size(size)
            .shaping(iced::widget::text::Shaping::Advanced).into()
    }
}

fn reaction_chip_style(selected: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |theme, status| {
        let mut style = ui_button(Tone::Canvas, Tone::Hover, Tone::Text, 18.0)(theme, status);
        style.border = Border::default().rounded(18)
            .width(if selected { 2 } else { 1 })
            .color(tone(theme, if selected { Tone::Accent } else { Tone::QuoteBar }));
        style
    }
}

fn message_action_icon(icon: Icon, label: impl Into<String>, action: Option<AppMessage>) -> Element<'static, AppMessage> {
    let quote = matches!(&icon, Icon::QuoteReply);
    hint(
        button(icon_tone(icon, Tone::Secondary, if quote { 20.0 } else { 18.0 }))
            .width(30)
            .height(30)
            .padding(if quote { 5 } else { 6 })
            .on_press_maybe(action)
            .style(ui_button(Tone::Transparent, Tone::Hover, Tone::Text, 4.0)),
        label,
    )
}

fn message_menu_action(icon: Icon, label: &str, action: Option<AppMessage>, role: Tone) -> Element<'static, AppMessage> {
    button(
        row![icon_tone(icon, role, 18.0), text(label.to_owned()).size(13).width(Fill)]
            .spacing(10)
            .align_y(Alignment::Center),
    )
    .width(Fill)
    .padding([8, 10])
    .on_press_maybe(action)
    .style(ui_button(Tone::Transparent, Tone::Hover, role, 4.0))
    .into()
}

fn message_popup_style(theme: &Theme) -> container::Style {
    let mut style = ui_surface(Tone::Surface, true, 6.0)(theme);
    style.shadow = iced::Shadow {
        color: Color::from_rgba(0.0, 0.0, 0.0, 0.24),
        offset: iced::Vector::new(0.0, 3.0),
        blur_radius: 12.0,
    };
    style
}

fn presence_icon(
    availability: presence::Availability,
    activity: presence::Activity,
    size: f32,
    appearance: Appearance,
) -> Element<'static, AppMessage> {
    if activity == presence::Activity::Presenting {
        return presenting_icon(size, appearance);
    }
    static HANDLES: std::sync::OnceLock<[[svg::Handle; 6]; 2]> = std::sync::OnceLock::new();
    let handles = HANDLES.get_or_init(|| {
        let sources: [&[u8]; 6] = [
            include_bytes!("../assets/icons/presence-available.svg"),
            include_bytes!("../assets/icons/presence-busy.svg"),
            include_bytes!("../assets/icons/presence-away.svg"),
            include_bytes!("../assets/icons/presence-dnd.svg"),
            include_bytes!("../assets/icons/presence-offline.svg"),
            include_bytes!("../assets/icons/presence-unknown.svg"),
        ];
        let states = [
            presence::Availability::Available,
            presence::Availability::Busy,
            presence::Availability::Away,
            presence::Availability::DoNotDisturb,
            presence::Availability::Offline,
            presence::Availability::Unknown,
        ];
        [Appearance::Light, Appearance::Dark].map(|appearance| {
            let theme = teams_theme(appearance);
            std::array::from_fn(|index| {
                let color = tone(&theme, presence_tone(states[index]));
                let css = format!(
                    "#{:02x}{:02x}{:02x}",
                    (color.r * 255.0).round() as u8,
                    (color.g * 255.0).round() as u8,
                    (color.b * 255.0).round() as u8,
                );
                // SVG tint recolors every pixel, including white check/minus
                // strokes. Bake the theme color into the shared handle instead.
                let source = String::from_utf8_lossy(sources[index]).replace("currentColor", &css);
                svg::Handle::from_memory(source.into_bytes())
            })
        })
    });
    let index = match availability {
        presence::Availability::Available | presence::Availability::AvailableIdle => 0,
        presence::Availability::Busy | presence::Availability::BusyIdle => 1,
        presence::Availability::BeRightBack | presence::Availability::Away => 2,
        presence::Availability::DoNotDisturb => 3,
        presence::Availability::Offline => 4,
        presence::Availability::Unknown => 5,
    };
    let theme_index = usize::from(appearance == Appearance::Dark);
    svg(handles[theme_index][index].clone())
        .width(size)
        .height(size)
        .into()
}

/// Presenting keeps a black dash on the red ball. The shared tint would paint
/// that dash the same red as the circle.
fn presenting_icon(size: f32, appearance: Appearance) -> Element<'static, AppMessage> {
    static HANDLES: std::sync::OnceLock<[svg::Handle; 2]> = std::sync::OnceLock::new();
    let handles = HANDLES.get_or_init(|| {
        [Appearance::Light, Appearance::Dark].map(|appearance| {
            let color = tone(&teams_theme(appearance), Tone::PresenceBusy);
            let css = format!(
                "#{:02x}{:02x}{:02x}",
                (color.r * 255.0).round() as u8,
                (color.g * 255.0).round() as u8,
                (color.b * 255.0).round() as u8,
            );
            let source = String::from_utf8_lossy(include_bytes!("../assets/icons/presence-presenting.svg"))
                .replace("currentColor", &css);
            svg::Handle::from_memory(source.into_bytes())
        })
    });
    svg(handles[usize::from(appearance == Appearance::Dark)].clone())
        .width(size)
        .height(size)
        .into()
}

