fn preview_line(value: &str, limit: usize) -> String {
    let single_line = value.split_whitespace().collect::<Vec<_>>().join(" ");
    if single_line.chars().count() <= limit {
        single_line
    } else {
        format!(
            "{}…",
            single_line.chars().take(limit - 1).collect::<String>()
        )
    }
}

fn group_messages(previous: &GraphMessage, next: &GraphMessage) -> bool {
    if previous.author != next.author
        || previous.author_id != next.author_id
        || previous.is_mine != next.is_mine
        || previous.date != next.date
    {
        return false;
    }
    let interval = chrono::DateTime::parse_from_rfc3339(&previous.timestamp)
        .ok()
        .zip(chrono::DateTime::parse_from_rfc3339(&next.timestamp).ok())
        .map(|(a, b)| (b - a).num_seconds())
        .or_else(|| {
            chrono::NaiveTime::parse_from_str(&previous.time, "%H:%M")
                .ok()
                .zip(chrono::NaiveTime::parse_from_str(&next.time, "%H:%M").ok())
                .map(|(a, b)| (b - a).num_seconds())
        });
    interval.is_some_and(|seconds| (0..=300).contains(&seconds))
}

fn group_messages_in_section(section: Section, previous: &GraphMessage, next: &GraphMessage) -> bool {
    group_messages(previous, next)
        && (section != Section::Teams
            || (previous.reply_to.is_some() && previous.reply_to == next.reply_to))
}

fn channel_thread_reply_hidden(
    message: &GraphMessage,
    collapsed_roots: &HashSet<String>,
) -> bool {
    message
        .reply_to
        .as_ref()
        .is_some_and(|root_id| collapsed_roots.contains(root_id))
}

fn initials(label: &str) -> String {
    use unicode_segmentation::UnicodeSegmentation;

    let mut words = label
        .split_whitespace()
        .filter_map(|word| word.graphemes(true).find(|grapheme| {
            grapheme.chars().next().is_some_and(char::is_alphabetic)
        }));
    let mut initials = words.next().unwrap_or("?").to_uppercase();
    if let Some(last) = words.last() {
        initials.push_str(&last.to_uppercase());
    }
    initials
}

fn avatar_colors(label: &str) -> (Color, Color) {
    let palette = [
        (0xe8e3ff, 0x493685),
        (0xdceeff, 0x205885),
        (0xd7f2e5, 0x20573f),
        (0xf6e9d5, 0x704f2f),
        (0xf1e1f5, 0x734780),
        (0xd4f1ef, 0x1c5c58),
        (0xf9e1e5, 0x812e48),
    ];
    let index = label
        .bytes()
        .fold(0usize, |sum, byte| sum.wrapping_add(byte as usize));
    let (background, foreground) = palette[index % palette.len()];
    (rgb(background), rgb(foreground))
}

