async fn cancellable_global_people_search(
    session: TeamsSession,
    query: String,
    mut cancellation: tokio::sync::oneshot::Receiver<()>,
) -> Result<(TeamsSession, Vec<PersonSearchResult>), String> {
    tokio::select! {
        biased;
        _ = &mut cancellation => return Err(tr("Search canceled.").into()),
        _ = futures_timer::Delay::new(Duration::from_millis(280)) => {}
    }
    graph::search_people_cancellable(session, &query, cancellation).await
}

fn global_people_search_task(
    session: TeamsSession,
    epoch: u64,
    sequence: u64,
    query: String,
    cancellation: tokio::sync::oneshot::Receiver<()>,
) -> Task<AppMessage> {
    let result_query = query.clone();
    // Iced polls tasks on its thread pool, which has no Tokio reactor. The
    // Graph client panics there and the dropdown stays on "Pesquisando…".
    Task::perform(
        background::run_interactive(move || {
            graph::runtime()?.block_on(cancellable_global_people_search(
                session,
                query,
                cancellation,
            ))
        }),
        move |result| AppMessage::GlobalPeopleSearchLoaded(epoch, sequence, result_query, result),
    )
}

async fn cancellable_global_message_search(
    session: TeamsSession,
    query: String,
    from: usize,
    debounce: bool,
    mut cancellation: tokio::sync::oneshot::Receiver<()>,
) -> Result<(TeamsSession, graph::MessageSearchPage), String> {
    if debounce {
        tokio::select! {
            biased;
            _ = &mut cancellation => return Err(tr("Search canceled.").into()),
            _ = futures_timer::Delay::new(Duration::from_millis(280)) => {}
        }
    }
    graph::search_messages_cancellable(
        session,
        &query,
        from,
        GLOBAL_MESSAGE_SEARCH_PAGE_SIZE,
        cancellation,
    )
    .await
}

fn global_message_search_task(
    session: TeamsSession,
    epoch: u64,
    sequence: u64,
    query: String,
    from: usize,
    debounce: bool,
    cancellation: tokio::sync::oneshot::Receiver<()>,
) -> Task<AppMessage> {
    let result_query = query.clone();
    Task::perform(
        background::run_interactive(move || {
            graph::runtime()?.block_on(cancellable_global_message_search(
                session,
                query,
                from,
                debounce,
                cancellation,
            ))
        }),
        move |result| {
            AppMessage::GlobalMessageSearchLoaded(epoch, sequence, result_query, from, result)
        },
    )
}

