            state.calendar_loading = false;
            match result {
                Ok((session, page)) => {
                    state.session = Some(session);
                    let previous = std::mem::take(&mut state.calendar_events);
                    let merged = calendar::merge_events(
                        if append { previous.clone() } else { Vec::new() },
                        page.events,
                    );
                    state.calendar_events = if append {
                        merged
                    } else {
                        calendar::retain_provisional(previous, merged)
                    };
                    state.calendar_next_link = page.next_link;
                    state.calendar_loaded = true;
                    state.calendar_error = None;
                }
                Err(error) => state.calendar_error = Some(error),
            }
