            let peers = state.selected_group_people.clone();
            let epoch = state.session_epoch;
            let request_title = title.clone();
            state.creating_group_chat = true;
            state.people_search_error = None;
            Task::perform(
                background::run(move || graph::create_group_chat(session, &owner, &request_title, &peers)),
                move |result| AppMessage::GroupChatCreated(epoch, title, result),
            )
