// Always retain the base as the first child. Switching the root between the
// conversation and a Stack would discard Iced's scroll/editor widget state.
fn conversation_overlay<'a>(
    base: Element<'a, AppMessage>,
    overlay: Element<'a, AppMessage>,
) -> Element<'a, AppMessage> {
    stack![base, overlay].width(Fill).height(Fill).into()
}

fn call_window_banner(state: &TeamsApp) -> Element<'_, AppMessage> {
    if state.call_window.is_none() && state.native_call.is_none() {
        return space::vertical().height(0).into();
    }
    let direct = state.prejoin.as_ref().is_some_and(|join| {
        join.chat_target.as_ref().is_some_and(|target| target.callee().is_some())
    });
    let status = state
        .native_call_snapshot
        .as_ref()
        .map(|snapshot| snapshot.phase.status(direct))
        .unwrap_or(tr("Call"));
    let subject = state
        .prejoin
        .as_ref()
        .map(|join| join.subject.trim())
        .filter(|subject| !subject.is_empty())
        .unwrap_or(tr("The call"));
    let mut actions = row![
        icon_tone(Icon::Calls, Tone::OnPrimary, 18.0),
        column![
            text(status).size(13).font(semibold()).color(Color::WHITE),
            text(subject).size(12).color(Color::WHITE),
        ].spacing(1).width(Fill),
    ].spacing(10).align_y(Alignment::Center);
    if state.call_window.is_some() {
        actions = actions.push(
            button(text(tr("Show")).size(13).font(semibold())).padding([6, 12])
                .on_press(AppMessage::FocusCallWindow)
                .style(ui_button(Tone::Primary, Tone::SelectedHover, Tone::OnPrimary, 4.0)),
        );
    }
    if state.native_call.is_some() {
        let label = if direct { tr("Hang up") } else { tr("Leave") };
        actions = actions.push(
            button(text(label).size(13).font(semibold())).padding([6, 12])
                .on_press(AppMessage::LeaveNativeMeeting)
                .style(ui_button(Tone::Danger, Tone::SelectedHover, Tone::OnPrimary, 4.0)),
        );
    }
    container(actions)
    .width(Fill)
    .padding([6, 14])
    .style(|_| iced::widget::container::Style {
        background: Some(Background::Color(rgb(0x303451))),
        ..Default::default()
    })
    .into()
}

fn meeting_started_banner(state: &TeamsApp) -> Element<'_, AppMessage> {
    let Some(notice) = state.meeting_started_notices.back() else {
        return space::vertical().height(0).into();
    };
    let can_chat = state.chats.iter().any(|chat| chat.id == notice.thread_id && chat.hidden != Some(true));
    let subject = if notice.subject.trim().is_empty() { tr("Meeting") } else { notice.subject.as_str() };
    let mut actions = row![
        icon_tone(Icon::Camera, Tone::OnPrimary, 18.0),
        text(format!("Meeting started: {}", preview_line(subject, 90))).size(14).color(Color::WHITE).width(Fill),
    ].spacing(10).align_y(Alignment::Center);
    if can_chat {
        actions = actions.push(button(text(tr("Message")).size(13)).padding([6, 10])
            .on_press(AppMessage::OpenMeetingStartedChat(notice.id.clone()))
            .style(ui_button(Tone::Transparent, Tone::Hover, Tone::OnPrimary, 4.0)));
    }
    actions = actions.push(button(text(tr("Join meeting")).size(13).font(semibold())).padding([6, 12])
            .on_press_maybe((state.native_call.is_none() && state.prejoin.is_none()).then(|| AppMessage::JoinMeetingStarted(notice.id.clone())))
            .style(ui_button(Tone::Primary, Tone::SelectedHover, Tone::OnPrimary, 4.0)))
        .push(hint(button(text("×").size(20)).padding([2, 8]).on_press(AppMessage::DismissMeetingStarted(notice.id.clone()))
            .style(ui_button(Tone::Transparent, Tone::Hover, Tone::OnPrimary, 4.0)), tr("Dismiss notification")));
    container(actions).width(Fill).padding([6, 14]).style(|_| iced::widget::container::Style {
        background: Some(Background::Color(rgb(0x303451))), ..Default::default()
    }).into()
}

