    #[test]
    fn meet_now_close_and_session_change_prevent_late_automatic_entry() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = true;
        state.section = Section::Calendar;
        state.meet_now = MeetNowState { open: true, busy: true, sequence: 7, subject: "Teste".into(), start_after_create: true, ..Default::default() };
        let epoch = state.session_epoch;
        drop(update_inner(&mut state, AppMessage::MeetNowCreate(true)));
        assert_eq!(state.meet_now.sequence, 7);
        drop(update_inner(&mut state, AppMessage::CloseMeetNow));
        let meeting = calendar_transport::InstantMeeting { subject: "Teste".into(), join_url: "https://teams.microsoft.com/meet/demo".into() };
        drop(update_inner(&mut state, AppMessage::MeetNowCreated(epoch, 7, Ok(meeting.clone()))));
        assert!(state.prejoin.is_none());
        assert!(state.meet_now.meeting.is_some());
        drop(update_inner(&mut state, AppMessage::OpenMeetNow));
        drop(update_inner(&mut state, AppMessage::MeetNowCreate(true)));
        assert_eq!(state.prejoin.as_ref().unwrap().input, meeting.join_url);

        state.prejoin = None;
        state.meet_now = MeetNowState { open: true, busy: true, sequence: 8, start_after_create: true, ..Default::default() };
        state.session_epoch += 1;
        drop(update_inner(&mut state, AppMessage::MeetNowCreated(epoch, 8, Ok(meeting))));
        assert!(state.prejoin.is_none());
        assert!(state.meet_now.meeting.is_none());
    }

