    #[test]
    fn mention_roster_without_wire_names_lists_people_already_bound_to_those_ids() {
        let mut state=TeamsApp::from_client_id(String::new());state.demo_mode=false;
        let owner="aaaaaaaa-1111-1111-1111-111111111111";
        let ana="bbbbbbbb-2222-2222-2222-222222222222";
        let unnamed="cccccccc-3333-3333-3333-333333333333";
        let chat="19:room@thread.v2";
        state.user_id=owner.into();state.user_name="Eu".into();
        state.section=Section::Chats;
        state.chats=vec![ChatSummary{id:chat.into(),title:"Projeto".into(),is_group:true,..Default::default()}];
        state.selected_chat=Some(chat.into());
        state.chat_messages_loaded_for=Some(chat.into());
        state.messages=vec![GraphMessage{id:"1".into(),author:"Ana Beatriz".into(),author_id:Some(format!("8:orgid:{ana}")),..Default::default()}];
        state.group_members=vec![ChatMemberSummary{mri:format!("8:orgid:{ana}"),person_id:Some(ana.into()),display_name:"Participante".into(),role:None}];
        state.draft="@".into();
        state.mention_composer.context(Some(chat.into()),true);
        state.mention_composer.caret=1;
        state.mention_composer.sync("@",&[]);
        let epoch=state.session_epoch;let sequence=state.mention_composer.sequence;
        let members=vec![
            ChatMemberSummary{mri:format!("8:orgid:{ana}"),person_id:Some(ana.into()),display_name:String::new(),role:Some("User".into())},
            ChatMemberSummary{mri:format!("8:orgid:{owner}"),person_id:Some(owner.into()),display_name:String::new(),role:Some("Admin".into())},
            ChatMemberSummary{mri:format!("8:orgid:{unnamed}"),person_id:Some(unnamed.into()),display_name:String::new(),role:None},
        ];
        let _=update_inner(&mut state,AppMessage::MentionMembersLoaded(epoch,sequence,chat.into(),Ok((TeamsSession::test_fixture(),members))));
        let choices=state.mention_composer.choices();
        assert!(choices.iter().any(|entry|entry.id==ana && entry.name=="Ana Beatriz" && !entry.everyone));
        assert!(choices.iter().any(|entry|entry.everyone && entry.name=="Everyone"));
        assert!(!choices.iter().any(|entry|entry.id==owner || entry.id==unnamed || entry.name=="Participante"));
    }
