    #[test]
    fn settings_pages_and_local_choices_preserve_drafts_and_never_start_audio() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.load_demo_data();
        let _ = update(&mut state, AppMessage::DraftChanged("Meu rascunho".into()));
        let selected = state.selected_chat.clone();
        let _ = update(&mut state, AppMessage::OpenSettings);
        for page in settings::Page::ALL {
            let _ = update(&mut state, AppMessage::SelectSettingsPage(page));
            assert_eq!(state.settings_page, page);
            assert!(state.audio_test_busy.is_none());
        }
        let cancellation = audio::AudioCancellation::new();
        state.audio_test_cancellation = Some(cancellation.clone());
        state.audio_wizard_step = Some(AudioWizardStep::Microphone);
        let _ = update(&mut state, AppMessage::SelectSettingsPage(settings::Page::Appearance));
        assert!(cancellation.is_cancelled());
        assert!(state.audio_wizard_step.is_none());
        let _ = update(&mut state, AppMessage::SelectSettingsPage(settings::Page::Devices));
        let _ = update(&mut state, AppMessage::EnterSendsChanged(false));
        let _ = update(&mut state, AppMessage::SkinToneChanged(preferences::SkinTone::Dark));
        let _ = update(&mut state, AppMessage::ResetReading);
        assert!(!state.preferences.enter_sends);
        assert_eq!(state.preferences.skin_tone, preferences::SkinTone::Dark);
        let _ = update(&mut state, AppMessage::CloseSettings);
        assert!(state.composer_uses_editor());
        assert_eq!(state.draft, "Meu rascunho");
        assert_eq!(state.selected_chat, selected);
        assert!(!state.preferences_saving);
        let _ = update(&mut state, AppMessage::InsertComposerEmoji("👍".into()));
        assert_eq!(state.draft, "Meu rascunho👍🏿");
        let _ = update(&mut state, AppMessage::SelectSettingsPage(settings::Page::Chats));
        assert_eq!(state.settings_page, settings::Page::Devices);
    }

