    #[test]
    fn sidebar_drag_is_bounded_ignores_invalid_coordinates_and_stops_on_release() {
        let mut state = TeamsApp::from_client_id(String::new());
        drop(update(&mut state, AppMessage::SidebarDragMoved(500.0)));
        assert_eq!(state.preferences.chat_sidebar_width, 426);
        drop(update(&mut state, AppMessage::StartSidebarResize));
        drop(update(&mut state, AppMessage::SidebarDragMoved(NAV_RAIL_WIDTH + 400.0)));
        assert_eq!(state.preferences.chat_sidebar_width, 400);
        drop(update(&mut state, AppMessage::SidebarDragMoved(f32::NAN)));
        assert_eq!(state.preferences.chat_sidebar_width, 400);
        drop(update(&mut state, AppMessage::SidebarDragMoved(9000.0)));
        assert_eq!(state.preferences.chat_sidebar_width, 560);
        drop(update(&mut state, AppMessage::SidebarDragMoved(-9000.0)));
        assert_eq!(state.preferences.chat_sidebar_width, 240);
        drop(update(&mut state, AppMessage::EndSidebarResize));
        assert!(!state.resizing_sidebar);
        drop(update(&mut state, AppMessage::SidebarDragMoved(500.0)));
        assert_eq!(state.preferences.chat_sidebar_width, 240);
    }

