    #[test]
    fn main_window_controls_target_chat_and_use_the_close_cleanup() {
        use window_chrome::Action;
        let mut state = TeamsApp::from_client_id(String::new());
        let main = iced::window::Id::unique();
        let call = iced::window::Id::unique();
        state.main_window = Some(main);
        state.call_window = Some(call);
        state.prejoin = Some(meeting::Prejoin::new(7, "Demo".into(), String::new()));

        assert!(!main_window_settings().decorations);
        assert!(main_window_settings().maximized);
        assert!(call_window_settings().decorations);
        assert!(!call_window_settings().maximized);
        assert_eq!(update_inner(&mut state, AppMessage::MainWindowAction(call, Action::Close)).units(), 0);
        assert!(state.prejoin.is_some());

        let resize = AppMessage::MainWindowAction(main, Action::Resize(iced::window::Direction::West));
        assert_eq!(update_inner(&mut state, resize.clone()).units(), 1);
        drop(update_inner(&mut state, AppMessage::MainWindowMaximized(call, true)));
        assert!(!state.main_window_maximized);
        drop(update_inner(&mut state, AppMessage::MainWindowMaximized(main, true)));
        assert_eq!(update_inner(&mut state, resize).units(), 0);

        let close = AppMessage::MainWindowAction(main, Action::Close);
        assert_eq!(update_inner(&mut state, close.clone()).units(), 3);
        assert!(state.closing_window);
        assert!(state.call_window.is_none());
        assert!(state.prejoin.is_none());
        assert_eq!(update_inner(&mut state, close).units(), 0);
    }

