    #[test]
    fn meeting_started_uses_confirmed_chat_signal_and_exact_calendar_match() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = true;
        let now = chrono::Utc::now();
        let thread = "19:meeting_fixture@thread.v2";
        let url = "https://teams.microsoft.com/l/meetup-join/19%3Ameeting_fixture%40thread.v2/0";
        let event = calendar::CalendarEvent {
            id:"fixture".into(), subject:"Reunião fictícia".into(), is_online:true, join_url:Some(url.into()),
            start:Some(calendar::CalendarDateTime { value:(now - chrono::Duration::minutes(1)).to_rfc3339(),time_zone:None }),
            end:Some(calendar::CalendarDateTime { value:(now + chrono::Duration::minutes(30)).to_rfc3339(),time_zone:None }),
            ..Default::default()
        };
        state.calendar_events = vec![event];
        let payload = serde_json::json!({"resourceType":"NewMessage","resource":{
            "id":"start-fixture","threadid":thread,"messagetype":"Event/Call",
            "content":"<partlist/>","composetime":now.to_rfc3339()
        }}).to_string();
        let push = || ost::event_hub::TrouterEvent { kind:ost::event_hub::TrouterEventKind::ChatService,payload_json:payload.clone() };
        apply_trouter_event(&mut state, push());
        apply_trouter_event(&mut state, push());
        assert_eq!(state.meeting_started_notices.len(), 1);
        assert_eq!(state.meeting_started_notices[0].subject, "Reunião fictícia");
        assert_eq!(state.meeting_started_notices[0].join_url, url);
        let id = state.meeting_started_notices[0].id.clone();
        let _ = update_inner(&mut state, AppMessage::JoinMeetingStarted(id));
        assert!(state.meeting_started_notices.is_empty());
        assert_eq!(state.prejoin.as_ref().unwrap().input, url);
        assert!(state.native_call.is_none(), "showing prejoin must not start a call");
        assert!(state.active_chat_meetings.contains_key(thread));
    }

    #[test]
    fn started_call_in_a_chat_shows_the_live_bar_without_a_calendar_entry() {
        let mut state = TeamsApp::from_client_id(String::new());
        let thread = "19:warroom_fixture@thread.v2";
        state.chats.push(ChatSummary {
            id: thread.into(), title: "War Room".into(), is_group: true, ..Default::default()
        });
        let now = chrono::Utc::now();
        let payload = serde_json::json!({"resourceType":"NewMessage","resource":{
            "id":"start-warroom","threadid":thread,"messagetype":"Event/Call",
            "content":"<partlist><part identity='8:orgid:a'><name>Marina Costa</name></part><part identity='8:orgid:b'><name>Paulo Nunes</name></part></partlist>",
            "composetime":now.to_rfc3339()
        }}).to_string();
        apply_trouter_event(&mut state, ost::event_hub::TrouterEvent {
            kind: ost::event_hub::TrouterEventKind::ChatService, payload_json: payload,
        });
        assert!(state.meeting_started_notices.is_empty(), "a start without one calendar match stays off the global banner");
        let chat = state.chats.iter().find(|chat| chat.id == thread).unwrap().clone();
        let meeting = state.detected_live_meeting(&chat).expect("the open chat shows the live bar");
        assert_eq!(meeting.subject, "War Room");
        assert!(meeting.join_url.is_empty());
        assert_eq!(meeting.participants, ["Marina Costa", "Paulo Nunes"]);
        assert_eq!(meeting.participant_count, 2);
        assert!(meeting.elapsed_secs < 5);
        let ended = serde_json::json!({"resourceType":"NewMessage","resource":{
            "id":"end-warroom","threadid":thread,"messagetype":"Event/Call","content":"<ended/>"
        }}).to_string();
        apply_trouter_event(&mut state, ost::event_hub::TrouterEvent {
            kind: ost::event_hub::TrouterEventKind::ChatService, payload_json: ended,
        });
        assert!(state.detected_live_meeting(&chat).is_none());
    }

