    #[test]
    fn refresh_marks_remote_message_unread_without_service_badge_and_keeps_read_races_safe() {
        let mut state = TeamsApp::from_client_id(String::new());
        let session = TeamsSession::test_fixture();
        state.session = Some(session.clone());
        state.section = Section::Chats;
        state.selected_chat = Some("other".into());
        let old = ChatSummary { id: "chat-1".into(), last_message_time: Some("2026-11-03T10:00:00Z".into()), ..Default::default() };
        state.chats = vec![old.clone()];
        let mut incoming = old;
        incoming.last_message_time = Some("2026-11-03T10:01:00Z".into());
        incoming.last_message_is_mine = Some(false);
        let loaded = |chats| LoadedChats { session: session.clone(), user_id: String::new(), user_name: String::new(), user_email: String::new(), company_name: String::new(), chats };
        let _task = update_inner(&mut state, AppMessage::RefreshedChats(0, 0, Ok(loaded(vec![incoming.clone()]))));
        assert_eq!(state.chats[0].unread, Some(true));
        let _task = update_inner(&mut state, AppMessage::RefreshedChats(0, 0, Ok(loaded(vec![incoming.clone()]))));
        assert_eq!(state.chats[0].unread, Some(true));
        record_successful_chat_read(&mut state, "chat-1", "message-1");
        incoming.unread = Some(true);
        let _task = update_inner(&mut state, AppMessage::RefreshedChats(0, 0, Ok(loaded(vec![incoming]))));
        assert_eq!(state.chats[0].unread, Some(false));
        assert!(state.realtime_chat_dirty);
    }

