    #[test]
    fn trouter_legacy_port_and_endpoint_path_enable_prejoin_without_weakening_origin_checks() {
        let mut state=TeamsApp::from_client_id(String::new());
        state.prejoin=Some(meeting::Prejoin::new(9,"Reunião fictícia".into(),"https://teams.microsoft.com/meet/fixture".into()));
        let event=|root:&str|ost::event_hub::TrouterEvent {
            kind:ost::event_hub::TrouterEventKind::TransportConnected,
            payload_json:serde_json::json!({"messagingRoot":root,"transportEndpointId":"fixture","ttlSeconds":60}).to_string(),
        };
        let connected=event("https://fixture.trouter.skype.com:3443/v4/opaque");
        state.call_hub.handle_event(connected.clone());
        apply_trouter_event(&mut state,connected);
        assert!(state.call_hub.context().is_some());
        assert!(state.calling_context.is_some());
        assert_eq!(state.trouter_failure,None);
        let callback=state.prejoin.as_ref().unwrap().call_callbacks.as_ref().unwrap().link(call_context::CallbackKind::Acceptance);
        let callback=url::Url::parse(callback).unwrap();
        assert_eq!(callback.port(),Some(3443));
        assert!(callback.path().starts_with("/v4/opaque/callAgent/"));
        let rejected=event("https://skype.com.evil.test/v4/opaque");
        state.call_hub.handle_event(rejected.clone());
        apply_trouter_event(&mut state,rejected);
        assert!(state.call_hub.context().is_none());
        assert!(state.calling_context.is_none());
        assert_eq!(state.trouter_failure,Some("metadata_host"));
        assert!(state.prejoin.as_ref().unwrap().call_callbacks.is_none());
    }

    #[test]
    fn native_call_callback_readiness_uses_the_existing_transport_and_clears_on_disconnect() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.prejoin = Some(meeting::Prejoin::new(
            1,
            "Fictitious meeting".into(),
            "https://teams.microsoft.com/meet/fixture".into(),
        ));
        let connected = |root: &str| ost::event_hub::TrouterEvent {
            kind: ost::event_hub::TrouterEventKind::TransportConnected,
            payload_json: serde_json::json!({"messagingRoot":root,
                "transportEndpointId":"fixture-endpoint","ttlSeconds":3600})
            .to_string(),
        };
        apply_trouter_event(
            &mut state,
            connected("https://fixture.trouter.skype.com/v4/opaque/"),
        );
        assert!(state.trouter_connected);
        assert!(state.calling_context.as_ref().unwrap().is_ready());
        assert!(state.prejoin.as_ref().unwrap().call_callbacks.is_some());
        let callback = state
            .prejoin
            .as_ref()
            .unwrap()
            .call_callbacks
            .as_ref()
            .unwrap()
            .link(call_context::CallbackKind::CallEnd)
            .to_owned();
        apply_trouter_event(
            &mut state,
            connected("https://fixture.trouter.skype.com/v4/opaque/"),
        );
        assert_eq!(
            state
                .prejoin
                .as_ref()
                .unwrap()
                .call_callbacks
                .as_ref()
                .unwrap()
                .link(call_context::CallbackKind::CallEnd),
            callback
        );
        apply_trouter_event(
            &mut state,
            ost::event_hub::TrouterEvent {
                kind: ost::event_hub::TrouterEventKind::TransportDisconnected,
                payload_json: String::new(),
            },
        );
        assert!(state.calling_context.is_none());
        assert!(state.prejoin.as_ref().unwrap().call_callbacks.is_none());
        assert_eq!(
            state.prejoin.as_ref().unwrap().input,
            "https://teams.microsoft.com/meet/fixture"
        );
        apply_trouter_event(&mut state, connected("https://evil.test/root/"));
        assert!(
            state.trouter_connected,
            "invalid call metadata must not break chat push state"
        );
        assert!(state.calling_context.is_none());
        apply_trouter_event(
            &mut state,
            connected("https://fixture.trouter.skype.com/v4/opaque/"),
        );
        state.stop_trouter();
        assert!(!state.trouter_connected);
        assert!(state.calling_context.is_none());
    }

