    #[test]
    fn meeting_chat_is_bound_to_call_generation_and_resolved_thread() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = true;
        state.user_name = "Pessoa fictícia".into();
        let target = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Afixture%40thread.v2/0").unwrap().chat_target().unwrap();
        let other = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Aother%40thread.v2/0").unwrap().chat_target().unwrap();
        assert!(!format!("{target:?}").contains("fixture"));
        let mut join = meeting::Prejoin::new(7,"Fixture".into(),String::new());
        join.call_panel = Some(meeting::CallPanel::Chat);
        join.chat.set_target(Some(target.clone()));
        join.chat.loading = true;
        let sequence = join.chat.sequence;
        state.prejoin = Some(join);
        state.native_call_snapshot = Some(native_call::Snapshot { phase:native_call::Phase::Connected,chat_target:Some(target.clone()),..Default::default() });
        let page = || Ok((TeamsSession::test_fixture(), graph::MessagePage { messages:vec![GraphMessage {id:"a".into(),body:"Olá".into(),..Default::default()}], before:None }));
        let epoch = state.session_epoch;
        let _ = update_inner(&mut state, AppMessage::MeetingChatLoaded(epoch, 6, sequence, target.clone(), page()));
        assert!(!state.prejoin.as_ref().unwrap().chat.loaded);
        let _ = update_inner(&mut state, AppMessage::MeetingChatLoaded(epoch, 7, sequence, target.clone(), page()));
        assert_eq!(state.prejoin.as_ref().unwrap().chat.messages.len(),1);
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("Resposta de exemplo".into()));
        let _ = update_inner(&mut state, AppMessage::MeetingChatSend);
        assert_eq!(state.prejoin.as_ref().unwrap().chat.messages.len(),2);
        assert!(state.prejoin.as_ref().unwrap().chat.draft.is_empty());
        state.prejoin.as_mut().unwrap().chat.draft = "Rascunho não enviado".into();
        state.prejoin.as_mut().unwrap().chat.end_session();
        let _ = update_inner(&mut state, AppMessage::MeetingChatLoaded(epoch, 7, sequence, target.clone(), page()));
        assert!(state.prejoin.as_ref().unwrap().chat.messages.is_empty());
        assert_eq!(state.prejoin.as_ref().unwrap().chat.draft, "Rascunho não enviado");
        state.prejoin.as_mut().unwrap().chat.set_target(Some(other.clone()));
        state.native_call_snapshot.as_mut().unwrap().chat_target=Some(other);
        let _ = update_inner(&mut state, AppMessage::MeetingChatLoaded(epoch, 7, sequence, target, page()));
        assert!(state.prejoin.as_ref().unwrap().chat.messages.is_empty());
        assert!(state.prejoin.as_ref().unwrap().chat.draft.is_empty(), "a different meeting must not inherit a draft");
    }

    #[test]
    fn meeting_chat_restores_account_drafts_only_for_the_matching_thread() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = false;
        state.drafts_loaded = false;
        state.user_id = "fixture-account".into();
        state.session = Some(TeamsSession::test_fixture());
        state.prejoin = Some(meeting::Prejoin::new(7, "Fixture".into(), String::new()));
        state.prejoin.as_mut().unwrap().call_panel = Some(meeting::CallPanel::Chat);
        let target = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Afirst%40thread.v2/0").unwrap().chat_target().unwrap();
        let other = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Asecond%40thread.v2/0").unwrap().chat_target().unwrap();
        state.native_call_snapshot = Some(native_call::Snapshot { phase: native_call::Phase::Connected, chat_target: Some(target.clone()), ..Default::default() });
        sync_meeting_chat_target(&mut state, 6, target.clone());
        assert!(state.prejoin.as_ref().unwrap().chat.target.is_none());
        sync_meeting_chat_target(&mut state, 7, target.clone());
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("não deve substituir o arquivo".into()));
        assert!(state.prejoin.as_ref().unwrap().chat.draft.is_empty());
        let mut loaded = drafts::LoadedDrafts::default();
        loaded.text.insert(target.draft_key(), "Rascunho salvo".into());
        loaded.text.insert(other.draft_key(), "Outro rascunho".into());
        let epoch = state.session_epoch;
        let _ = update_inner(&mut state, AppMessage::DraftsLoaded(epoch, "fixture-account".into(), Ok(loaded)));
        assert_eq!(state.prejoin.as_ref().unwrap().chat.draft, "Rascunho salvo");
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("Continuação".into()));
        assert_eq!(state.drafts.get(&target.draft_key()).map(String::as_str), Some("Continuação"));
        state.prejoin = Some(meeting::Prejoin::new(8, "Fixture".into(), String::new()));
        sync_meeting_chat_target(&mut state, 8, target.clone());
        assert_eq!(state.prejoin.as_ref().unwrap().chat.draft, "Continuação");
        sync_meeting_chat_target(&mut state, 8, other.clone());
        assert_eq!(state.prejoin.as_ref().unwrap().chat.draft, "Outro rascunho");
        assert_ne!(target.draft_key(), format!("chat:{}", target.as_str()));
        state.prejoin.as_mut().unwrap().call_panel = Some(meeting::CallPanel::Chat);
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("não pertence à chamada atual".into()));
        assert_eq!(state.drafts.get(&other.draft_key()).map(String::as_str), Some("Outro rascunho"));
    }

    #[test]
    fn meeting_chat_send_preserves_newer_even_identical_drafts() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = true;
        let target = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Afixture%40thread.v2/0").unwrap().chat_target().unwrap();
        let mut join = meeting::Prejoin::new(7, "Fixture".into(), String::new());
        join.call_panel = Some(meeting::CallPanel::Chat);
        join.chat.set_target(Some(target.clone()));
        join.chat.loaded = true;
        state.prejoin = Some(join);
        state.native_call_snapshot = Some(native_call::Snapshot { phase: native_call::Phase::Connected, chat_target: Some(target.clone()), ..Default::default() });
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("Olá".into()));
        let attempt = chat_state::SendAttempt::prepare(None, target.as_str().into(), "Olá".into());
        let sent_revision = state.prejoin.as_ref().unwrap().chat.draft_revision;
        state.prejoin.as_mut().unwrap().chat.sending = true;
        state.prejoin.as_mut().unwrap().chat.send_sequence = 1;
        state.prejoin.as_mut().unwrap().chat.send_attempt = Some(attempt.clone());
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("Olá".into()));
        let result = || Ok((TeamsSession::test_fixture(), GraphMessage { id: "sent".into(), body: "Olá".into(), is_mine: true, ..Default::default() }));
        let epoch = state.session_epoch;
        let _ = update_inner(&mut state, AppMessage::MeetingChatSent(epoch, 7, 1, sent_revision, target.clone(), attempt.clone(), result()));
        assert_eq!(state.prejoin.as_ref().unwrap().chat.draft, "Olá");
        assert_eq!(state.drafts.get(&target.draft_key()).map(String::as_str), Some("Olá"));
        let current_revision = state.prejoin.as_ref().unwrap().chat.draft_revision;
        state.prejoin.as_mut().unwrap().chat.sending = true;
        state.prejoin.as_mut().unwrap().chat.send_sequence = 2;
        state.prejoin.as_mut().unwrap().chat.send_attempt = Some(attempt.clone());
        let _ = update_inner(&mut state, AppMessage::MeetingChatSent(epoch, 7, 2, current_revision, target.clone(), attempt, result()));
        assert!(state.prejoin.as_ref().unwrap().chat.draft.is_empty());
        assert!(!state.drafts.contains_key(&target.draft_key()));
    }

    #[test]
    fn meeting_chat_retry_reuses_id_but_ignores_old_call_responses() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = false;
        state.drafts_loaded = true;
        state.session = Some(TeamsSession::test_fixture());
        let target = meeting::JoinLink::parse("https://teams.microsoft.com/l/meetup-join/19%3Afixture%40thread.v2/0").unwrap().chat_target().unwrap();
        let mut join = meeting::Prejoin::new(7, "Fixture".into(), String::new());
        join.call_panel = Some(meeting::CallPanel::Chat);
        join.chat.set_target(Some(target.clone()));
        join.chat.loaded = true;
        state.prejoin = Some(join);
        state.native_call_snapshot = Some(native_call::Snapshot { phase: native_call::Phase::Connected, chat_target: Some(target.clone()), ..Default::default() });
        let _ = update_inner(&mut state, AppMessage::MeetingChatDraftChanged("Olá".into()));
        // The returned task is deliberately not polled: no network operation is started.
        drop(send_meeting_chat(&mut state));
        let first = state.prejoin.as_ref().unwrap().chat.send_attempt.clone().unwrap();
        let old_sequence = state.prejoin.as_ref().unwrap().chat.send_sequence;
        let revision = state.prejoin.as_ref().unwrap().chat.draft_revision;
        state.prejoin.as_mut().unwrap().chat.end_session();
        state.prejoin.as_mut().unwrap().chat.loaded = true;
        drop(send_meeting_chat(&mut state));
        let retry = state.prejoin.as_ref().unwrap().chat.send_attempt.clone().unwrap();
        let new_sequence = state.prejoin.as_ref().unwrap().chat.send_sequence;
        assert_eq!(first.client_id, retry.client_id);
        assert_ne!(old_sequence, new_sequence);
        let epoch = state.session_epoch;
        let _ = update_inner(&mut state, AppMessage::MeetingChatSent(epoch, 7, old_sequence, revision, target.clone(), first, Err("erro antigo".into())));
        assert!(state.prejoin.as_ref().unwrap().chat.sending);
        let _ = update_inner(&mut state, AppMessage::MeetingChatSent(epoch, 7, new_sequence, revision, target.clone(), retry,
            Ok((TeamsSession::test_fixture(), GraphMessage { id: "sent".into(), body: "Olá".into(), is_mine: true, ..Default::default() }))));
        assert!(state.prejoin.as_ref().unwrap().chat.draft.is_empty());
        assert!(!state.retry_sends.contains_key(&target.draft_key()));
    }

