        state.audio_test_busy = Some(AudioTestKind::Speaker);
        let _ = update_inner(&mut state, AppMessage::SpeakerTestFinished(Ok(())));
        assert!(state.audio_wizard_action_ready);
        let _ = update_inner(&mut state, AppMessage::AudioWizardSpeakerFeedback(true));
        assert_eq!(state.audio_wizard_speaker_heard, Some(true));
        assert_eq!(state.audio_wizard_step, Some(AudioWizardStep::Microphone));
        assert!(!state.audio_wizard_action_ready);

        state.audio_test_busy = Some(AudioTestKind::LocalEcho);
        let _ = update_inner(&mut state, AppMessage::LocalEchoFinished(Ok(())));
        assert!(state.audio_wizard_action_ready);
