        let internal = ChatSummary { id: "48:notifications".into(), hidden: Some(true), unread: Some(true), ..Default::default() };
        for filter in [ChatListFilter::Recent, ChatListFilter::Hidden, ChatListFilter::Unread] {
            assert!(!chat_matches_filter(&internal, filter));
        }
        let real = ChatSummary { id: "19:project@thread.v2".into(), title: "Notifications".into(), is_group: true, ..Default::default() };
        let cached = vec![hidden_chats::HiddenChat { id: internal.id.clone(), title: "Notifications".into(), is_group: false }];
