    #[test]
    fn hide_and_restore_demo_chat_uses_a_separate_hidden_filter() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = true;
        state.load_demo_data();
        let hidden_id = state.selected_chat.clone().expect("demo chat selected");

        let _ = update_inner(&mut state, AppMessage::SetSelectedChatHidden(true));
        assert_eq!(
            state
                .chats
                .iter()
                .find(|chat| chat.id == hidden_id)
                .and_then(|chat| chat.hidden),
            Some(true)
        );
        assert_ne!(state.selected_chat.as_deref(), Some(hidden_id.as_str()));
        assert_eq!(state.chat_list_filter, ChatListFilter::Recent);

        let _ = update_inner(
            &mut state,
            AppMessage::SetChatListFilter(ChatListFilter::Hidden),
        );
        assert_eq!(state.chat_list_filter, ChatListFilter::Hidden);
        state.selected_chat = Some(hidden_id.clone());
        let _ = update_inner(&mut state, AppMessage::SetSelectedChatHidden(false));
        assert_eq!(
            state
                .chats
                .iter()
                .find(|chat| chat.id == hidden_id)
                .and_then(|chat| chat.hidden),
            Some(false)
        );
        assert_eq!(state.chat_list_filter, ChatListFilter::Recent);
    }

