    #[test]
    fn message_mutations_only_target_own_persisted_chat_messages() {
        let own = GraphMessage {
            id: "server:42".into(),
            body: "Revisar proposta".into(),
            is_mine: true,
            ..Default::default()
        };
        assert!(message_can_edit(&own));
        assert!(message_can_delete(&own));

        let incoming = GraphMessage {
            is_mine: false,
            ..own.clone()
        };
        let pending = GraphMessage {
            id: "local:pending".into(),
            ..own.clone()
        };
        let rich = GraphMessage {
            rich: Some(std::sync::Arc::new(message_body::Document::plain("Rich"))),
            ..own.clone()
        };
        let deleted = GraphMessage {
            is_deleted: true,
            ..own.clone()
        };
        assert!(!message_can_edit(&incoming));
        assert!(!message_can_delete(&incoming));
        assert!(!message_can_edit(&pending));
        assert!(!message_can_delete(&pending));
        assert!(message_can_edit(&rich));
        let mention=GraphMessage{rich:message_body::Document::from_html("<p><at>Ana</at>, olá</p>").map(std::sync::Arc::new),..own.clone()};
        assert!(!message_can_edit(&mention),"editing cannot discard typed mention identities");
        assert!(message_can_delete(&rich));
        assert!(!message_can_edit(&deleted));
        assert!(!message_can_delete(&deleted));
    }

