    #[test]
    fn image_overlay_round_trip_retains_the_conversation_widget_state() {
        use iced::advanced::widget::{Tree, tree};
        fn layers(open: bool) -> Element<'static, AppMessage> {
            let base = scrollable(iced::widget::column![text("Conversation")]).into();
            let overlay: Element<'static, AppMessage> = if open {
                container(text("Image viewer")).into()
            } else { space::vertical().into() };
            conversation_overlay(base, overlay)
        }
        let initial = layers(false);
        let mut tree = Tree::new(initial.as_widget());
        // Sentinel in the native scrollable state slot detects subtree replacement.
        // No layout/event calls are made while this test sentinel occupies the slot.
        tree.children[0].state = tree::State::new(471_u32);
        for open in [true, false, true, false] {
            let view = layers(open);
            tree.diff(view.as_widget());
            assert_eq!(*tree.children[0].state.downcast_ref::<u32>(), 471);
        }
    }

    #[test]
    fn image_viewer_navigation_is_bounded_and_resets_per_image_zoom() {
        let urls = ["0-one", "0-two"].map(|id| images::InlineImage {
            id: id.into(),
            url: format!("https://api.asm.skype.com/v1/objects/{id}/views/imgo"),
            ..Default::default()
        });
        let mut viewer = ImageViewer {
            scope: "chat:fixture".into(),
            images: urls.into(),
            index: 0,
            original: None,
            loading: false,
            error: None,
            feedback: None,
            busy: false,
            zoom: 1.0,
        };
        viewer.zoom_by(20);
        assert_eq!(viewer.zoom, 5.0);
        assert!(!viewer.navigate(-1));
        assert!(viewer.navigate(1));
        assert_eq!(viewer.index, 1);
        assert_eq!(viewer.zoom, 1.0);
        assert!(viewer.loading);
        assert!(!viewer.navigate(-1));
        assert!(!viewer.navigate(1));
        viewer.zoom_by(-20);
        assert_eq!(viewer.zoom, 0.25);
        viewer.zoom = 1.0;
        viewer.zoom_by_wheel(1.0);
        assert!((viewer.zoom - 1.1).abs() < 0.001);
        viewer.zoom_by_wheel(-1.0);
        assert!((viewer.zoom - 1.0).abs() < 0.001);
        viewer.zoom_by_wheel(f32::NAN);
        assert!((viewer.zoom - 1.0).abs() < 0.001);
    }

