    #[test]
    fn rich_composer_can_toggle_formatting_before_typing() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.formatting_open = true;
        state.composer_content = crate::composer_decorations::Content::with_text("");
        let draft_key = state.draft_key().unwrap();

        let _ = update(
            &mut state,
            AppMessage::ApplyDraftMark(message_body::InlineMark::Bold),
        );
        assert!(state.draft_active_marks[&draft_key].contains(&message_body::InlineMark::Bold));

        for character in ['T', 'e', 's', 't'] {
            let _ = update(
                &mut state,
                AppMessage::DraftAction(text_editor::Action::Edit(
                    text_editor::Edit::Insert(character),
                )),
            );
        }
        let formatting = &state.draft_formatting[&draft_key];
        assert_eq!(state.draft, "Test");
        assert!(formatting.has_mark(0, 4, message_body::InlineMark::Bold));

        let _ = update(
            &mut state,
            AppMessage::ApplyDraftMark(message_body::InlineMark::Bold),
        );
        let _ = update(
            &mut state,
            AppMessage::DraftAction(text_editor::Action::Edit(
                text_editor::Edit::Insert('!'),
            )),
        );
        assert_eq!(state.draft, "Test!");
        assert!(!state.draft_formatting[&draft_key].has_mark(
            0,
            5,
            message_body::InlineMark::Bold
        ));
        assert!(state.draft_formatting[&draft_key].has_mark(
            0,
            4,
            message_body::InlineMark::Bold
        ));
    }

