    #[test]
    fn profile_menu_opens_status_editor_and_closes_without_changing_draft() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.draft = "Rascunho preservado".into();
        state.presence.set_demo_status_note("Em foco".into());

        let _ = update_inner(&mut state, AppMessage::ToggleProfileMenu);
        assert!(state.profile_menu_open);
        let _ = update_inner(&mut state, AppMessage::OpenProfilePresence);
        assert!(state.profile_presence_open);
        let _ = update_inner(&mut state, AppMessage::CloseNewConversation);
        assert!(state.profile_menu_open);
        assert!(!state.profile_presence_open);
        let _ = update_inner(&mut state, AppMessage::OpenProfilePresence);
        let _ = update_inner(&mut state, AppMessage::PresenceSelected(presence::Availability::Away));
        assert!(!state.profile_presence_open);
        assert_eq!(state.presence.selected_own(Instant::now()), Some(presence::Availability::Away));
        let _ = update_inner(&mut state, AppMessage::CloseProfileMenu);
        assert!(!state.profile_menu_open);

        let _ = update_inner(&mut state, AppMessage::ToggleProfileMenu);
        let _ = update_inner(&mut state, AppMessage::CloseNewConversation);
        assert!(!state.profile_menu_open);
        assert_eq!(state.draft, "Rascunho preservado");

        let _ = update_inner(&mut state, AppMessage::ToggleProfileMenu);
        let _ = update_inner(&mut state, AppMessage::OpenStatusNote);
        assert!(!state.profile_menu_open);
        assert!(state.status_note_open);
        assert_eq!(state.status_note_content.text(), "Em foco");
        let _ = update_inner(&mut state, AppMessage::CloseNewConversation);
        assert!(!state.status_note_open);
        assert_eq!(state.draft, "Rascunho preservado");
    }

