    #[test]
    fn image_draft_keeps_multiple_attachments_ordered_and_removes_only_the_selected_item() {
        let mut state = TeamsApp::from_client_id(String::new());
        let key = state.draft_key().unwrap();
        let first_batch = (0..3).map(|_| images::demo_image()).collect::<Vec<_>>();
        let keys = first_batch
            .iter()
            .map(|picture| picture.key.clone())
            .collect::<Vec<_>>();
        for picture in first_batch {
            let _ = update(
                &mut state,
                AppMessage::ImageFileStaged(0, key.clone(), Ok(picture)),
            );
        }
        assert_eq!(
            state.image_drafts[&key]
                .iter()
                .map(|picture| picture.key.as_str())
                .collect::<Vec<_>>(),
            keys.iter().map(String::as_str).collect::<Vec<_>>()
        );

        let _ = update(&mut state, AppMessage::RemoveImage(keys[1].clone()));
        assert_eq!(
            state.image_drafts[&key]
                .iter()
                .map(|picture| picture.key.as_str())
                .collect::<Vec<_>>(),
            vec![keys[0].as_str(), keys[2].as_str()]
        );

        for _ in 2..images::MAX_IMAGES {
            let _ = update(
                &mut state,
                AppMessage::ImageFileStaged(0, key.clone(), Ok(images::demo_image())),
            );
        }
        assert_eq!(state.image_drafts[&key].len(), images::MAX_IMAGES);
        let _ = update(
            &mut state,
            AppMessage::ImageFileStaged(0, key.clone(), Ok(images::demo_image())),
        );
        assert_eq!(state.image_drafts[&key].len(), images::MAX_IMAGES);
        assert!(state.status.contains("image limit"));
    }

