    #[test]
    fn enter_shows_the_message_before_the_server_answers() {
        use iced::advanced::widget::Tree;
        performance::start_counting();
        let mut state = TeamsApp::from_client_id(String::new());
        state.demo_mode = false;
        let panel = state.message_panel("Teste", "", &state.messages, false, iced::Size::new(1050.0, 840.0), false);
        let mut tree = Tree::new(panel.as_widget());
        drop(panel);
        let builds = performance::history_builds();
        assert!(builds >= 1);
        let _ = update(&mut state, AppMessage::DraftChanged("Oi".into()));
        state.begin_send("Oi");
        let client = state.pending_send.as_ref().unwrap().client_id.clone();
        state.show_outgoing_now(&client, "Oi", None, None, None, None, None);
        assert_eq!(state.draft, "");
        assert_eq!(state.messages.last().map(|message| message.body.as_str()), Some("Oi"));
        assert!(state.messages.last().unwrap().id.starts_with("local:"));
        assert!(state.shown_chat_history < state.messages.len());
        let panel = state.message_panel("Teste", "", &state.messages, false, iced::Size::new(1050.0, 840.0), false);
        tree.diff(panel.as_widget());
        drop(panel);
        assert_eq!(performance::history_builds(), builds);
        let _ = update(
            &mut state,
            AppMessage::MessageSent("chat-ana".into(), Err("falhou".into())),
        );
        assert!(state.messages.iter().all(|message| message.body != "Oi"));
        assert_eq!(state.draft, "Oi");
        assert_eq!(state.shown_chat_history, state.messages.len());
    }

    #[test]
    fn enter_clears_the_composer_before_the_server_answers() {
        let mut state = TeamsApp::from_client_id(String::new());
        let _ = update(&mut state, AppMessage::DraftChanged("Olá".into()));
        state.begin_send("Olá");
        assert!(state.draft.is_empty());
        assert!(state.sending_message);
        // Keys already queued on the old widget arrive as the previous text plus the new ones.
        let _ = update(&mut state, AppMessage::DraftChanged("Oláa".into()));
        let _ = update(&mut state, AppMessage::DraftChanged("Oláab".into()));
        assert_eq!(state.draft, "ab");
        let _ = update(&mut state, AppMessage::ComposerSettled);
        let _ = update(&mut state, AppMessage::DraftChanged("abc".into()));
        assert_eq!(state.draft, "abc");
        state.confirm_send();
        assert_eq!(state.draft, "abc");
    }

