    #[test]
    fn conversation_search_highlights_and_navigates_loaded_messages_without_touching_draft() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.selected_chat = Some("chat-ana".into());
        state.messages = vec![
            GraphMessage {
                id: "first-match".into(),
                author: "Ana".into(),
                body: "Deploy starts at noon".into(),
                ..Default::default()
            },
            GraphMessage {
                id: "non-match".into(),
                author: "Bruno".into(),
                body: "I will review the patch".into(),
                ..Default::default()
            },
            GraphMessage {
                id: "last-match".into(),
                author: "Carla".into(),
                body: "The deploy is complete".into(),
                ..Default::default()
            },
        ];
        state.draft = "keep this unsent draft".into();
        state.message_search_open = true;

        let _ = update_inner(&mut state, AppMessage::MessageSearchChanged(" DEPLOY ".into()));
        assert_eq!(state.selected_message.as_deref(), Some("last-match"));
        assert_eq!(state.message_search_result_index, 1);
        assert_eq!(state.draft, "keep this unsent draft");

        let _ = update_inner(&mut state, AppMessage::NavigateMessageSearch(-1));
        assert_eq!(state.selected_message.as_deref(), Some("first-match"));
        let _ = update_inner(&mut state, AppMessage::NavigateMessageSearch(1));
        assert_eq!(state.selected_message.as_deref(), Some("last-match"));
        assert_eq!(state.draft, "keep this unsent draft");

        let _ = update_inner(&mut state, AppMessage::MessageSearchChanged("not present".into()));
        assert_eq!(state.selected_message, None);
        assert_eq!(state.message_search_result_index, 0);

        state.follow_tail = false;
        state.pending_history_anchor = Some(HistoryViewport {
            chat_id: "chat-ana".into(),
            at_bottom: false,
            offset_y: 200.0,
            content_height: 4000.0,
            viewport_height: 600.0,
            viewport_width: 1000.0,
            compact: false,
        });
        let _ = update_inner(&mut state, AppMessage::ToggleMessageSearch);
        assert!(!state.message_search_open);
        assert!(state.message_search_query.is_empty());
        assert!(state.follow_tail);
        assert!(state.pending_history_anchor.is_none());
        assert_eq!(state.draft, "keep this unsent draft");
    }

