    #[test]
    fn older_conversation_search_stops_after_its_page_budget_or_cursor_end() {
        let mut search = PendingConversationSearch {
            epoch: 2,
            chat_id: "chat-ana".into(),
            query: "release".into(),
            pages_remaining: CONVERSATION_SEARCH_PAGE_BUDGET,
        };
        let mut fetched = 0;
        loop {
            fetched += 1;
            if !search.consume_page(true) {
                break;
            }
        }
        assert_eq!(fetched, usize::from(CONVERSATION_SEARCH_PAGE_BUDGET));
        assert_eq!(search.pages_remaining, 0);

        let mut search = PendingConversationSearch {
            pages_remaining: 8,
            ..search
        };
        assert!(!search.consume_page(false));
        assert_eq!(search.pages_remaining, 7);
    }

