    #[test]
    fn channel_message_grouping_keeps_roots_separate_and_groups_replies_by_thread() {
        let message = |id: &str, reply_to: Option<&str>, time: &str| GraphMessage {
            id: id.into(),
            author: "Ana".into(),
            author_id: Some("ana".into()),
            date: "2026-10-27".into(),
            time: time.into(),
            reply_to: reply_to.map(str::to_owned),
            ..Default::default()
        };
        let first_root = message("root-1", None, "10:01");
        let next_root = message("root-2", None, "10:02");
        let first_reply = message("reply-1", Some("root-1"), "10:01");
        let next_reply = message("reply-2", Some("root-1"), "10:02");
        let other_thread_reply = message("reply-3", Some("root-2"), "10:03");

        assert!(!group_messages_in_section(
            Section::Teams,
            &first_root,
            &next_root
        ));
        assert!(group_messages_in_section(
            Section::Teams,
            &first_reply,
            &next_reply
        ));
        assert!(!group_messages_in_section(
            Section::Teams,
            &next_reply,
            &other_thread_reply
        ));
        assert!(group_messages_in_section(
            Section::Chats,
            &first_root,
            &next_root
        ));
    }

