    #[test]
    fn reply_origin_navigation_walk_is_bounded_and_can_continue_on_retry() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.section = Section::Chats;
        state.selected_chat = Some("chat-ana".into());
        state.history_before = Some("older-page".into());
        state.pending_reply_origin_navigation = Some(PendingReplyOriginNavigation {
            epoch: state.session_epoch,
            chat_id: "chat-ana".into(),
            message_id: "message-parent".into(),
            pages_remaining: REPLY_ORIGIN_PAGE_BUDGET,
        });

        for remaining in (0..REPLY_ORIGIN_PAGE_BUDGET).rev() {
            assert!(matches!(
                advance_reply_origin_navigation(&mut state),
                ReplyOriginNavigationProgress::Loading(_)
            ));
            assert_eq!(
                state
                    .pending_reply_origin_navigation
                    .as_ref()
                    .unwrap()
                    .pages_remaining,
                remaining
            );
        }
        assert!(matches!(
            advance_reply_origin_navigation(&mut state),
            ReplyOriginNavigationProgress::Exhausted
        ));
        assert!(state.pending_reply_origin_navigation.is_none());
        assert!(state.status.contains("previous 12 pages"));

        state.pending_reply_origin_navigation = Some(PendingReplyOriginNavigation {
            epoch: state.session_epoch,
            chat_id: "chat-ana".into(),
            message_id: "message-parent".into(),
            pages_remaining: REPLY_ORIGIN_PAGE_BUDGET,
        });
        assert!(matches!(
            advance_reply_origin_navigation(&mut state),
            ReplyOriginNavigationProgress::Loading(_)
        ));
        assert_eq!(
            state
                .pending_reply_origin_navigation
                .as_ref()
                .unwrap()
                .pages_remaining,
            REPLY_ORIGIN_PAGE_BUDGET - 1
        );
    }

