    #[test]
    fn native_reaction_without_wire_names_resolves_roster_and_avatar_identity() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.load_group_avatar_demo();
        let a = "33333333-3333-3333-3333-333333333333";
        let b = "44444444-4444-4444-4444-444444444444";
        let reaction = ost::api::ReactionCount { emoji: "❤️".into(), count: 3,
            reactors: vec![
                ost::api::Reactor { id: format!("8:orgid:{a}"), name: String::new() },
                ost::api::Reactor { id: format!("8:orgid:{b}"), name: String::new() },
                ost::api::Reactor { id: "unknown-id".into(), name: String::new() },
            ] };
        let participants = resolved_reaction_participants(&reaction, "", &state.identity_names());
        assert_eq!(participants[0].name, "Bruno");
        assert_eq!(participants[1].name, "Camila");
        assert_eq!(participants[2].name, "Unnamed participant");
        assert!(state.avatars.photo(participants[0].person_id.as_deref().unwrap()).is_some());
        assert!(state.avatars.photo(participants[1].person_id.as_deref().unwrap()).is_some());
        // Named wire identities retain their authoritative name.
        let mut named = reaction;
        named.reactors[0].name = "Bruno Silva".into();
        assert_eq!(resolved_reaction_participants(&named, "", &state.identity_names())[0].name, "Bruno Silva");
    }

