    #[test]
    fn service_ack_keeps_reaction_on_loaded_old_message_through_stale_refresh() {
        let mut state = TeamsApp::from_client_id(String::new());
        let session = TeamsSession::test_fixture();
        state.session = Some(session.clone());
        state.messages = vec![GraphMessage { id: "42".into(), ..Default::default() }];
        let epoch = state.session_epoch;
        state.pending_reactions.push(PendingReaction {
            epoch, chat_id: "chat-ana".into(), message_id: "42".into(), emoji: "😮".into(), remove: false,
        });
        let _unpolled = update_inner(&mut state, AppMessage::ReactionMutationFinished(
            epoch, "chat-ana".into(), "42".into(), "😮".into(), false, Ok((session.clone(), ())),
        ));
        assert_eq!(state.messages[0].reactions[0].emoji, "😮");
        assert!(user_reacted(&state.messages[0].reactions[0], &state.user_id));
        let sequence = state.reaction_refresh_sequences["chat-ana"];
        // A latest-page refresh may omit a target loaded by older pagination.
        let _ = update_inner(&mut state, AppMessage::ReactionMessagesLoaded {
            epoch, refresh_sequence: sequence, chat_id: "chat-ana".into(), message_id: "42".into(),
            emoji: "😮".into(), remove: false, result: Ok((session.clone(), MessagePage { messages: vec![], before: None })),
        });
        assert!(state.pending_reactions.is_empty());
        assert_eq!(state.messages[0].reactions[0].count, 1);
        // An older read projection cannot erase the acknowledged membership.
        let _ = update_inner(&mut state, AppMessage::RefreshedMessages(epoch, "chat-ana".into(), Ok((session,
            MessagePage { messages: vec![GraphMessage { id: "42".into(), ..Default::default() }], before: None },
        ))));
        assert_eq!(state.messages[0].reactions[0].count, 1);
    }

