    #[test]
    fn read_receipt_marks_own_messages_through_a_known_peer_frontier() {
        let messages = vec![
            GraphMessage {
                id: "out-1".into(),
                is_mine: true,
                ..Default::default()
            },
            GraphMessage {
                id: "out-2".into(),
                is_mine: true,
                ..Default::default()
            },
            GraphMessage {
                id: "in-3".into(),
                ..Default::default()
            },
        ];
        let receipts = vec![ost::api::ReadReceipt {
            user: "8:orgid:peer".into(),
            message_id: "in-3".into(),
            horizon: "10;10;in-3".into(),
        }];
        assert_eq!(
            read_receipt_marker_indices(&messages, &receipts, "me"),
            HashSet::from([0, 1])
        );
        let self_receipt = vec![ost::api::ReadReceipt {
            user: "8:orgid:ME".into(),
            message_id: "in-3".into(),
            horizon: "10;10;in-3".into(),
        }];
        assert!(read_receipt_marker_indices(&messages, &self_receipt, "me").is_empty());
    }

    #[test]
