    #[test]
    fn cancelled_document_upload_keeps_the_attachment_for_retry() {
        let mut state = TeamsApp::from_client_id(String::new());
        let (cancel, _) = tokio::sync::watch::channel(false);
        let draft = DocumentDraft {
            path: std::path::PathBuf::from("/tmp/report.pdf"),
            name: "report.pdf".into(),
            size: 2048,
            sha256: "a".repeat(64),
            client_message_id: "attempt-1".into(),
            publication_attempted: true,
        };
        state.document_drafts.insert("chat:source".into(), draft);
        state.document_upload = Some(DocumentUploadProgress {
            epoch: 0,
            attempt_id: 1,
            draft_key: "chat:source".into(),
            client_message_id: "attempt-1".into(),
            sent: 1024,
            total: 2048,
            cancel,
            cancel_requested: true,
        });
        state.sending_message = true;

        let _ = update(
            &mut state,
            AppMessage::DocumentUploadFinished(
                0,
                "chat:source".into(),
                "attempt-1".into(),
                DocumentUploadOutcome::Cancelled,
            ),
        );

        assert!(!state.sending_message);
        assert!(state.document_upload.is_none());
        assert_eq!(state.document_drafts["chat:source"].client_message_id, "attempt-1");
        assert!(state.status.contains("still in the draft"));
    }

    #[test]
    fn failed_document_upload_preserves_its_idempotency_key_for_retry() {
        let mut state = TeamsApp::from_client_id(String::new());
        let (cancel, _) = tokio::sync::watch::channel(false);
        state.document_drafts.insert(
            "chat:source".into(),
            DocumentDraft {
                path: std::path::PathBuf::from("/tmp/plan.docx"),
                name: "plan.docx".into(),
                size: 4096,
                sha256: "b".repeat(64),
                client_message_id: "attempt-retry".into(),
                publication_attempted: true,
            },
        );
        state.document_upload = Some(DocumentUploadProgress {
            epoch: 0,
            attempt_id: 1,
            draft_key: "chat:source".into(),
            client_message_id: "attempt-retry".into(),
            sent: 2048,
            total: 4096,
            cancel,
            cancel_requested: false,
        });
        state.sending_message = true;

        let _ = update(
            &mut state,
            AppMessage::DocumentUploadFinished(
                0,
                "chat:source".into(),
                "attempt-retry".into(),
                DocumentUploadOutcome::Completed(Err("temporary failure".into())),
            ),
        );

        assert!(!state.sending_message);
        assert_eq!(state.document_drafts["chat:source"].client_message_id, "attempt-retry");
        assert!(state.document_drafts["chat:source"].publication_attempted);
        assert_eq!(state.status, "temporary failure");
    }

    #[test]
    fn document_upload_progress_ignores_stale_updates_and_clamps_current_bytes() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.session_epoch = 4;
        let (cancel, _) = tokio::sync::watch::channel(false);
        state.document_upload = Some(DocumentUploadProgress {
            epoch: 4,
            attempt_id: 5,
            draft_key: "chat:source".into(),
            client_message_id: "attempt-1".into(),
            sent: 0,
            total: 100,
            cancel,
            cancel_requested: false,
        });

        let _ = update(
            &mut state,
            AppMessage::DocumentUploadProgress(3, 5, "chat:source".into(), 90, 100),
        );
        assert_eq!(state.document_upload.as_ref().unwrap().sent, 0);

        let _ = update(
            &mut state,
            AppMessage::DocumentUploadProgress(4, 4, "chat:source".into(), 80, 100),
        );
        assert_eq!(state.document_upload.as_ref().unwrap().sent, 0);

        let _ = update(
            &mut state,
            AppMessage::DocumentUploadProgress(4, 5, "chat:source".into(), 120, 100),
        );
        assert_eq!(state.document_upload.as_ref().unwrap().sent, 100);
        assert_eq!(state.document_upload.as_ref().unwrap().total, 100);
    }

    #[test]
    fn document_attachment_is_bounded_and_cannot_replace_an_existing_draft() {
        let mut state = TeamsApp::from_client_id(String::new());
        let path = std::env::temp_dir().join(format!(
            "teams-linux-document-{}-{}.pdf",
            std::process::id(),
            rand::random::<u64>()
        ));
        std::fs::write(&path, b"test file").unwrap();

        let task = state.stage_document_file("chat:source".into(), path.clone());
        drop(task);
        let fingerprint = file_upload::fingerprint_file(&path, MAX_DOCUMENT_BYTES).unwrap();
        let epoch = state.session_epoch;
        let _ = update_inner(
            &mut state,
            AppMessage::DocumentFileFingerprinted(
                epoch,
                "chat:source".into(),
                Ok(fingerprint),
            ),
        );
        let first_id = state.document_drafts["chat:source"].client_message_id.clone();
        let task = state.stage_document_file("chat:source".into(), path.clone());
        drop(task);

        assert_eq!(state.document_drafts["chat:source"].client_message_id, first_id);
        assert!(state.status.contains("Remove the current file"));
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn document_fingerprint_completion_is_scoped_to_the_pending_session_and_draft() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.session_epoch = 4;
        let path = std::env::temp_dir().join(format!(
            "teams-linux-document-hash-{}-{}.pdf",
            std::process::id(),
            rand::random::<u64>()
        ));
        std::fs::write(&path, b"original").unwrap();
        drop(state.stage_document_file("chat:source".into(), path.clone()));
        let fingerprint = file_upload::fingerprint_file(&path, MAX_DOCUMENT_BYTES).unwrap();

        let _ = update_inner(
            &mut state,
            AppMessage::DocumentFileFingerprinted(
                3,
                "chat:source".into(),
                Ok(fingerprint.clone()),
            ),
        );
        assert!(state.document_drafts.is_empty());
        assert!(state.pending_document_stage.is_some());

        let _ = update_inner(
            &mut state,
            AppMessage::DocumentFileFingerprinted(
                4,
                "chat:source".into(),
                Ok(fingerprint.clone()),
            ),
        );
        assert_eq!(
            state.document_drafts["chat:source"].sha256,
            fingerprint.sha256
        );
        assert!(state.pending_document_stage.is_none());

        std::fs::write(&path, b"modified").unwrap();
        let modified = file_upload::fingerprint_file(&path, MAX_DOCUMENT_BYTES).unwrap();
        assert_eq!(modified.size, fingerprint.size);
        assert_ne!(modified.sha256, fingerprint.sha256);
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn sending_is_blocked_while_the_current_draft_attachment_is_preparing() {
        let mut state = TeamsApp::from_client_id(String::new());
        state.selected_chat = Some("chat-source".into());
        state.draft = "Text beside the file".into();
        state.pending_document_stage = Some(PendingDocumentStage {
            epoch: state.session_epoch,
            draft_key: "chat:chat-source".into(),
            path: std::path::PathBuf::from("/tmp/pending.pdf"),
            name: "pending.pdf".into(),
            size: 128,
        });

        let _ = update_inner(&mut state, AppMessage::SendMessage);

        assert!(state.pending_send.is_none());
        assert_eq!(state.draft, "Text beside the file");
        assert_eq!(state.status, "Wait for the attachment to finish preparing.");
    }

